csui.define('d2/commands/doc.preview',[
  'require', 'nuc/lib/underscore', 'nuc/lib/jquery', 'nuc/lib/backbone', 'dctmw/utils/rest.resources',
  'csui/models/command', 'csui/utils/commandhelper',
  'csui/utils/commands/open.plugins/open.plugins',
  'csui/utils/commands/open.document/delegates/open.document.delegates',
  'd2/dialogs/document.preview/document.preview.plugin.mixin',
  'd2/dialogs/document.preview/document.preview.plugins',
  'd2/commands/open.plugins/impl/iviewer.preview.plugin',
  'd2/utils/constants',
  'd2/utils/server.query.utils',
  'd2/utils/widget.constants',
  'nuc/utils/url',
  'd2/controls/globalmessage/globalmessage',
  'i18n!d2/commands/nls/localized.strings'
], function (require, _, $, Backbone, RestResources, CommandModel, CommandHelper, openPlugins, openDocumentDelegates,
             DocumentPreviewPluginMixin, docPreviewPlugins, IViewerPreviewPlugin, constants, serverQueryUtils,
             widgetConstants, Url, GlobalMessage, lang) {
  'use strict';

  var DocPreviewCommand = CommandModel.extend({
    defaults: {
      signature: 'DocPreview',
      command_key: 'DocPreview',
      scope: 'multiple',
      name: lang.DocumentPreview
    },

    enabled: function (status, options) {
      var node = CommandHelper.getJustOneNode(status),
          disablePreview = status && status.targetView && status.targetView.disablePreview,
          previewPlugin = node && docPreviewPlugins.findByNode(node);

      if (!disablePreview && previewPlugin && this.collection) { /* last part of the condition is to make sure that this command is never enabled as part of OpenDocumentDelegates chain */
        var openDelegates = openDocumentDelegates.findByNode(node, status, options),
            openDelegateCmd = (openDelegates.get('signature') || '').toLowerCase(),
            plugin = openPlugins.findByNode(node, {
              openInNewTab: false
            });

        if (openDelegateCmd !== 'open' || !plugin || plugin.widgetView !== this.widgetView) {
          return true;
        }
      }
      var isMultiFileViewQualified = true;
      var modelObjects = status.nodes.models;
        if(modelObjects.length>=1 && modelObjects.length <= RestResources.getD2Options().max_files_allowed_for_multifile_view_iv) {
            for (var i = 0; i < modelObjects.length; i++) {
              var selectedItem = modelObjects[i];
              var previewPluginAvailable = docPreviewPlugins.findByNode(selectedItem);
              if(previewPluginAvailable === undefined || !(previewPluginAvailable instanceof IViewerPreviewPlugin)) {
                isMultiFileViewQualified = false;
                break;
              }
            }
            return isMultiFileViewQualified;
        }
      return false;
    },

    execute: function (status, options) {
      options = options || {};
      var me = this, deferred = $.Deferred();
      status.suppressSuccessMessage = true;
      status.suppressFailMessage = true;

      var originatingView = status.originatingView && status.originatingView.options &&
          status.originatingView.options.originatingView ?
              status.originatingView.options.originatingView : status.originatingView,
          highlightElement = originatingView && originatingView.$el.find($(event.target)).closest('tr');

      if (highlightElement && !highlightElement.length) {
        highlightElement = originatingView && originatingView.$el.find('tr.binf-active');
      }

      let node;
      let cloneNodes;
      if(status.nodes.models.length>1) {
      cloneNodes = new Backbone.Collection(status.nodes.map(function(node) {
                      return node.clone();
                    }));
      node = cloneNodes.at(0);
      cloneNodes.each(function(node){
        node.previewType = constants.ComparableDocumentPreviewTypes.MULTI_FILE_VIEW;
      });
      } else {
      node = CommandHelper.getJustOneNode(status);
      }
      if (status.nodes.models.length === 1) {
        me.isMipProtected(status, node).done(function(isEnabled) {
          if(isEnabled) {
            deferred.resolve();
          } else {
            me._openDocumentPreview({
              context: status.context || options.context,
              node: node,
              nodes: cloneNodes,
              highlightElement: highlightElement
            }).done(deferred.resolve).fail(deferred.reject);
          }
        }).fail(deferred.reject);
        return deferred.promise();
      }

      return this._openDocumentPreview({
        context: status.context || options.context,
        node: node,
        nodes: cloneNodes,
        highlightElement: highlightElement
      });
    },

    isMipProtected: function(status, node) {
      var deferred = $.Deferred(), me = this;

      csui.require(['d2/commands/open'],
          function (OpenCommand) {
            var cmdOptions = {
              context: status.context,
            };
            var openCmd = new OpenCommand();

            me.getDownloadLinkFromOpenCmd(openCmd, node).done(function(downloadLink) {
              var plugin = openPlugins.findByNode(node);
              if(plugin && _.isFunction(plugin.isOverridePDF) && plugin.isOverridePDF(node)) {
                downloadLink = Url.appendQuery(downloadLink, Url.combineQueryString({"content-id": node.get('i_contents_id')}));
              }
              var bravaCSRAnnotationsLink = openCmd.getBravaCSRAnnotationsLink(node),
                  bravaCSRAnnotationsListLink = openCmd.getBravaCSRAnnotationsListLink(node),
                  bravaCSRRasterURLsLink = openCmd.getBravaCSRRasterURLsLink(node),
                  bravaCSRChangemarkConfigLink = openCmd.getBravaCSRChangemarkConfigLink(node);
              openCmd.fetchDownloadUrls(node, downloadLink).done(function (downloadUrls, pageServingUrls, bravacsrSearchInfoUrl,
                                                                           bravacsrSearchInfoFallbackUrl, formats, pageCount, downloadLocationPath) {
                node['_download_urls_'] = downloadUrls;
                node['_page_serving_urls_'] = pageServingUrls;
                node['_page_count_'] = pageCount;
                node['_download_formats_'] = formats;
                node['_bravacsr_searchinfo_url_'] = bravacsrSearchInfoUrl;
                node['_bravacsr_searchInfo_fallback_url_'] = bravacsrSearchInfoFallbackUrl;
                node['_bravacsr_annotations_link_'] = bravaCSRAnnotationsLink;
                node['_bravacsr_annotations_list_link_'] = bravaCSRAnnotationsListLink;
                node['_bravacsr_raster_urls_link_'] = bravaCSRRasterURLsLink;
                node['_bravacsr_changemark_config_link_'] = bravaCSRChangemarkConfigLink;
                if(node.get('isPreviewProtected') === true) {
                  cmdOptions.isMIPEnabled = true
                  openCmd._showDownloadDialog(cmdOptions, node, downloadUrls, downloadLocationPath).done(function() {
                    deferred.resolve(true);
                  }).fail(deferred.reject);
                } else {
                  deferred.resolve(false);
                }
              }).fail(function(error) {
                GlobalMessage.showMessage("error", error.message, error.details);
                deferred.reject();
              });
            }).fail(deferred.reject);
      });
      return deferred.promise();
    },

    getDownloadLinkFromOpenCmd: function(openCmd, node) {
      var deferred = $.Deferred(), downloadLink = openCmd.getDownloadLink(node);
      if(!downloadLink) {
        openCmd.fetchLatestNode(node).done(function(newNode) {
          downloadLink = openCmd.getDownloadLink(newNode);
          deferred.resolve(downloadLink);
        }).fail(deferred.reject);
      } else {
        return deferred.resolve(downloadLink).promise();
      }
      return deferred.promise();
    }
  });

  DocumentPreviewPluginMixin.mixin(DocPreviewCommand.prototype);

  return DocPreviewCommand;
});

csui.define('d2/commands/viewer/compare.base.command',[
  'nuc/lib/jquery',
  'nuc/lib/backbone',
  'nuc/lib/underscore',
  'csui/models/command',
  'dctmw/utils/rest.resources',
  'd2/utils/server.query.utils',
  'd2/utils/widget.constants',
], function ($, Backbone, _, CommandModel, RestResources, serverQueryUtils, widgetConstants) {
  'use strict';

  var notSupportedExtensions = {
    "mp3": "mp3",
    "mp4": "mp4",
    "F4V": "F4V",
    "MOV": "MOV",
    "m4v": "m4v",
    "mpeg-4v": "mpeg-4v",
    "3gp": "3gp",
    "dat": "dat"
  };

  var supportedExtensionsForTextCompare = {
    "pdf": "pdf",
    "txt": "txt",
  };

  var CompareBaseCommand = CommandModel.extend({

    constructor: function CompareBaseCommand(/*attributes, options*/) {
      this.previewNodes = new Backbone.Collection();

      this.listenTo(this.previewNodes, 'update:viewer:markup:count', function (markupCounts) {
        this.previewNodes.originalNodes.each(function(node) {
          var objData = markupCounts[node.get("id")];
          if(node.get("viewer_markup_count") != objData.markup_count) {
            node.set("viewer_markup_count", objData.markup_count);
          }
        });
      });
      CommandModel.prototype.constructor.call(this, arguments);
    },

    getAllNotSupportedContentTypes: function (iViewer) {
      var contentTypes = [], formatCollection;
      if (this.allNotSupportedContentTypes) {
        return this.allNotSupportedContentTypes;
      }
      var nonSupportedTypes = notSupportedExtensions;
      if(iViewer) {
        var types = this.getTypesFromWidgetParam('iv_g_compare_format_unsupported');
        if(!_.isEmpty(types)) {
          nonSupportedTypes = types;
        }
      }
      formatCollection = RestResources.getFormats();
      if (formatCollection && !_.isEmpty(formatCollection)) {
        formatCollection.each(function (data) {
          if (nonSupportedTypes[data.get('dos_extension')]) {
            contentTypes.push(data.get('name'));
          }
        });
      }
      this.allNotSupportedContentTypes = contentTypes;
      return contentTypes;
    },

    getAllSupportedContentTypesForGraphicalCompare: function (iViewer) {
      var contentTypes = {}, supportedTypes = {}, formatCollection;
      if (this.allSupportedContentTypesForGraphicalCompare) {
        return this.allSupportedContentTypesForGraphicalCompare;
      }
      if(iViewer) {
        supportedTypes = this.getTypesFromWidgetParam('iv_g_compare_format');
      }
      formatCollection = RestResources.getFormats();
      if (formatCollection && !_.isEmpty(formatCollection)) {
        formatCollection.each(function (data) {
          if(iViewer) {
            if (supportedTypes && supportedTypes[data.get('dos_extension')]) {
              contentTypes[data.get('name')] = data.get('name');
            }
          } else {
            if (!notSupportedExtensions[data.get('dos_extension')]) {
              contentTypes[data.get('name')] = data.get('name');
            }
          }
        });
      }
      this.allSupportedContentTypesForGraphicalCompare = contentTypes;
      return contentTypes;
    },

    getAllSupportedContentTypesForTextCompare: function (iViewer) {
      var contentTypes = {}, formatCollection;
      if (this.allSupportedContentTypesForTextCompare) {
        return this.allSupportedContentTypesForTextCompare;
      }
      formatCollection = RestResources.getFormats();
      var supportedTypes = supportedExtensionsForTextCompare;
      if(iViewer) {
        supportedTypes = this.getTypesFromWidgetParam('iv_t_compare_format');
      }
      if (formatCollection && !_.isEmpty(formatCollection)) {
        formatCollection.each(function (data) {
          if (supportedTypes && supportedTypes[data.get('dos_extension')]) {
            contentTypes[data.get('name')] = data.get('name');
          }
        });
      }
      this.allSupportedContentTypesForTextCompare = contentTypes;
      return contentTypes;
    },

    getContentType: function (node) {
      return node.get('aContentType') || node.get('a_content_type');
    },

    getTypesFromWidgetParam: function(param) {
      var formatTypes = {}, userDefaultWidgets = RestResources.getCurrentUser().get('defaultWidgets');
      var ivWidgetConfiguration = null;
      if (userDefaultWidgets && !_.isEmpty(userDefaultWidgets)) {
        ivWidgetConfiguration = serverQueryUtils.getWidgetConfig(widgetConstants.D2.BRAVAIV, userDefaultWidgets[widgetConstants.DEFAULT.BRAVAIV]);
        var types = ivWidgetConfiguration['widgetParams'] && ivWidgetConfiguration['widgetParams'][param];
        types = types && types.split(",");
        if(types && types.length > 0) {
          formatTypes = _.reduce(types, function(result, value) {
            result[value.trim()] =  value.trim();
            return result;
          }, {});
        }
      }
      return formatTypes;
    },

    _blockActions: function (status) {
      if(status && status.originatingView && status.originatingView.blockActions) {
        status.originatingView.blockActions();
      } else {
        $('div.load-container.csui-global').removeClass('binf-hidden');
      }
    },

    _unblockActions: function (status) {
      if(status && status.originatingView && status.originatingView.unblockActions) {
        status.originatingView.unblockActions();
      } else {
        $('div.load-container.csui-global').addClass('binf-hidden');
      }
    }

  });

  return CompareBaseCommand;
});


csui.define('d2/commands/viewer/compare.text',[
  'nuc/lib/jquery',
  'nuc/lib/backbone',
  'nuc/lib/underscore',
  'csui/utils/commandhelper',
  'd2/controls/globalmessage/globalmessage',
  'd2/commands/viewer/compare.base.command',
  'd2/commands/open.plugins/impl/bravaviewer.preview.plugin',
  'd2/commands/open.plugins/impl/iviewer.preview.plugin',
  'd2/dialogs/document.preview/document.preview.plugins',
  'd2/dialogs/document.preview/document.preview.plugin.mixin',
  'd2/utils/constants',
  'd2/utils/server.query.utils',
  'd2/utils/widget.constants',
  'dctmw/utils/rest.resources',
  'd2/commands/open.plugins/impl/iviewer/utils',
  'i18n!d2/commands/nls/localized.strings'
], function ($, Backbone, _, CommandHelper, GlobalMessage, CompareBaseCommand, BravaViewerPreviewPlugin,
             IViewerPreviewPlugin, docPreviewPlugins, DocumentPreviewPluginMixin, constants,
             serverQueryUtils, widgetConstants, RestResources, iviewerUtils, lang) {
  'use strict';

  var CompareText = CompareBaseCommand.extend({

    defaults: {
      signature: 'D2-CompareText',
      command_key: 'D2-CompareText',
      name: lang.CompareTextName,
      scope: 'multiple'
    },

    enabled: function(status/*, options*/) {
      var enable = false;
      if (status.nodes && status.nodes.length === 2) {
        var node = status.nodes.at(0);
        var previewPlugin = node && docPreviewPlugins.findByNode(node);
        this.isIViewer = previewPlugin instanceof IViewerPreviewPlugin;
        this.isBravaViewer = previewPlugin instanceof BravaViewerPreviewPlugin;
        var userDefaultWidgets = RestResources.getCurrentUser().get('defaultWidgets');
        var ivTextEnabled = false, ivWidgetConfiguration = null;
        if (this.isIViewer && userDefaultWidgets && !_.isEmpty(userDefaultWidgets)) {
          ivWidgetConfiguration = serverQueryUtils.getWidgetConfig(widgetConstants.D2.BRAVAIV, userDefaultWidgets[widgetConstants.DEFAULT.BRAVAIV]);
          ivTextEnabled = ivWidgetConfiguration['widgetParams'] && ivWidgetConfiguration['widgetParams']['is_iv_t_compare_enabled'];
        }
        if((this.isBravaViewer || (this.isIViewer && ivTextEnabled)) && this.validateContentTypeOfAllNodes(status.nodes)) {
          enable = true;
        }
        if(this.isIViewer && iviewerUtils.hasRegularLicense === 0) {
          enable = false;
        }
      }
      return enable;
    },

    validateContentTypeOfAllNodes: function(nodeCollection) {
      var valid = true, supportedContentTypes = this.getAllSupportedContentTypesForTextCompare(this.isIViewer);
      nodeCollection.each(function(node) {
        var contentType = this.getContentType(node);
        if (!supportedContentTypes[contentType]) {
          valid = false;
        }
      }, this);

      return valid;
    },

    execute: function (status, options) {
      this.previewNodes.reset(status.nodes.map(function(node) {
        var cloneNode = node.clone();
        return cloneNode;
      }));
      var node = this.previewNodes.at(0);
      this.previewNodes.originalNodes = status.nodes;
      this.previewNodes.each(function(node) {
        node.previewType = constants.ComparableDocumentPreviewTypes.TEXT_COMPARE;
      });
      status.suppressSuccessMessage = true;

      var context = status.context || options.context;
      //open viewer
      this.openDocumetPreview(context, node);
    },

    openDocumetPreview: function(context, node) {
      return this._openDocumentPreview({
        context: context,
        node: node,
        nodes: this.previewNodes,
        highlightElement: false
      });
    }

  });

  DocumentPreviewPluginMixin.mixin(CompareText.prototype);

  return CompareText;
});


