csui.define('d2/commands/workflow/show.workflow.history',[
  'nuc/lib/underscore',
  'nuc/lib/jquery',
  'csui/models/command',
  'csui/utils/commandhelper',
  'csui/utils/contexts/factories/application.scope.factory',
  'd2/utils/constants',
  'dctmw/utils/user.preference.storage',
  'd2/utils/contexts/factories/widget.view.state.factory',
  'i18n!d2/commands/nls/localized.strings'
], function (_, $, CommandModel, CommandHelper, ApplicationScopeModelFactory, constants, userPreference, WidgetViewStateModelFactory, lang) {
  'use strict';

  return CommandModel.extend({
    defaults: {
      signature: 'D2-ShowWorkflowHistory',
      command_key: 'D2-ShowWorkflowHistory',
      name: lang.CommandNameShowWorkflowHistory,
      scope: 'single'
    },
    execute: function (status, options) {
      var context = status.context || options.context,
        appScope = context.getModel(ApplicationScopeModelFactory),
        viewStateModel = context.viewStateModel,
        node = CommandHelper.getJustOneNode(status),
        qParamData = JSON.stringify({
          'document-id': node.get('id'),
          'wf-states': [constants.WorkflowState.SCHEDULED, constants.WorkflowState.PAUSED, constants.WorkflowState.RUNNING]
        }),
        widgetViewStateModel = context.getObject(WidgetViewStateModelFactory);

      widgetViewStateModel && widgetViewStateModel.set('qform-param', qParamData);
      userPreference.saveLocalStorePreference(userPreference.StorageTypes.SEARCH_PANEL_VISIBILITY, constants.WidgetId.WORKFLOWS, true);
      viewStateModel.set('enabled', true);
      appScope.set('id', 'allworkflows');
      /*
       Root perspective plugin implementations are depending on view state model for building URL.
       If URL is not cleared from View state model, then same filter is applied in workflow list perspective also.
       For avoid this behavior, clearing filter from view state model and
       clearing filter from collection for avoiding fecth call from browsable mixin on filter value change.
      */
      status.collection.clearFilter(false);
      var state = viewStateModel.get(viewStateModel.CONSTANTS.STATE) || {};
      state = _.clone(state);
      state['filter'] = '';
      state['order_by'] = '';
      state['page'] = '';
      state['qform-param'] = '';
      viewStateModel.set(viewStateModel.CONSTANTS.STATE, state);
      return $.Deferred().resolve().promise();
    }
  });
});

csui.define('d2/commands/mass.update/mass.update',[
  'require',
  'nuc/lib/jquery',
  'nuc/lib/underscore',
  'nuc/lib/backbone',
  'nuc/utils/url',
  'csui/models/command',
  'csui/models/fileuploads',
  'csui/utils/commandhelper',
  'csui/utils/contexts/factories/connector',
  'csui/utils/taskqueue',
  'd2/controls/globalmessage/globalmessage',
  'dctmw/dialogs/modal.alert.custom.content/customizable.modal.alert',
  'd2/utils/rest.linkrels',
  'd2/utils/constants',
  'dctmw/server.adaptors/converters/node',
  'd2/utils/mass.update.utils',
  'dctmw/utils/utils',
  'i18n!d2/commands/nls/localized.strings'
], function (require, $, _, Backbone, Url, CommandModel, UploadFileCollection, CommandHelper, ConnectorFactory, TaskQueue, GlobalMessage, CustomizableModalAlert,
             RestLinkrels, constants, nodeConverter, massUpdateUtils, utils, lang) {
  'use strict';

  var configToIncludeOptionsMap = Object.freeze({
    'Update files in selected folders and files in any sub-folders': [constants.MassUpdateOptions.FILES_IN_SUB_FOLDERS],
    'Update files in selected folders and all descendents of any virtual documents': [constants.MassUpdateOptions.VIRTUAL_DOCUMENTS_DESCENDANTS],
    'Update files in selected folders, files in any sub-folders and all descendents of any virtual documents': [constants.MassUpdateOptions.FILES_IN_SUB_FOLDERS, constants.MassUpdateOptions.VIRTUAL_DOCUMENTS_DESCENDANTS],
    'Update selected folders and sub-folders': [constants.MassUpdateOptions.SUB_FOLDERS]
  });

  return CommandModel.extend({

    defaults: {
      signature: 'D2-MassUpdate',
      command_key: 'D2-MassUpdate',
      name: lang.MassUpdateCommandName,
      scope: 'multiple'
    },

    _fetchMassupdateConfig: function (node, options) {
      return $.ajax(node.connector.extendAjaxOptions({
        url: CommandHelper.getOriginalActionLink(node, this.get('signature'), RestLinkrels.D2_MASS_UPDATE_CONFIG, null, options.data)
      }));
    },

    _showOptionsDialog: function (options) {
      var dfd = $.Deferred(),
        me = this;

      if (options['is_massupdate_options_dialog_enabled']) {
        me._showMassUpdateOptionsDialog(options).done(dfd.resolve).fail(dfd.reject);
      } else {
        var includeOptions = configToIncludeOptionsMap[options['sv_file_option']] ? configToIncludeOptionsMap[options['sv_file_option']].slice() : [];
        configToIncludeOptionsMap[options['sv_folder_option']]
        && includeOptions.push.apply(includeOptions, configToIncludeOptionsMap[options['sv_folder_option']].slice());
        options['include_all_versions'] && includeOptions.push(constants.MassUpdateOptions.ALL_VERSIONS);
        dfd.resolve({
          'include-options': includeOptions,
          'update-types': constants.MassUpdateOptions.ITEM_PROPERTIES
        });
      }

      return dfd.promise();
    },

    _showMassUpdateOptionsDialog: function (options) {
      var dfd = $.Deferred(),
        buttonOptions = {
          showYes: true,
          labelYes: lang.MassUpdateDialogLabelYes,
          showNo: false,
          showCancel: true
        };

      csui.require(['d2/dialogs/mass.update/mass.update.options.dialog/mass.update.options.dialog'], function (MassUpdateOptionsDialog) {
        var contentView = new MassUpdateOptionsDialog(options);

        CustomizableModalAlert.confirmQuestion(function (result) {
          if (result) {
            dfd.resolve(contentView.options['form-data']);
          } else {
            dfd.reject('close');
          }
        }, '', lang.MassUpdateDialogTitle, {
          buttons: buttonOptions,
          contentView: contentView,
          className: 'd2-mass-update-form'
        });
      });

      return dfd.promise();
    },

    execute: function (status, options) {
      status.d2SelectedNodes = status.nodes;
      status.nodes = status.nodes.clone();
      options = options || {};

      var me = this;
      options.commandPromise = $.Deferred();
      // Avoid messages from handleExecutionResults. We use our own evaluation here and show message.
      status.suppressFailMessage = true;
      status.suppressSuccessMessage = true;

      this._executeMassUpdate(status, options).done(function (massUpdateData) {
        var data = massUpdateData.data;
        me._blockActions(status.originatingView);
        me.refreshNodes(status, data).always(function () {
          if (massUpdateData.ignoreSuccessMessage !== true) {
            var configName = options.massUpdateConfig['massupdate_config_label'] || options.massUpdateConfig['massupdate_config_name'];
            GlobalMessage.showMessage('success', _.str.sformat(lang.MassUpdateSuccessMessage, configName));
          }
          me._unblockActions(status.originatingView);
          options.commandPromise.resolve();
        });
      }).fail(_.bind(me.handleError, me, status, options));
      return options.commandPromise.promise();
    },
    handleError: function (status, options, error) {
      if (error !== 'close') {
        var errorMessage = error && error.responseText ? utils.parseAjaxErrorAsString(error) : typeof error === 'string' ? error : '',
          configName = options.massUpdateConfig && (options.massUpdateConfig['massupdate_config_label'] || options.massUpdateConfig['massupdate_config_name']);
        this.showErrorMessage(status, configName, errorMessage);
      }
      this._unblockActions(status.originatingView);
      options.commandPromise.reject();
    },

    showErrorMessage: function (status, configName, errorMessage) {
      var node = CommandHelper.getJustOneNode(status),
        nodes = [node?node:status.nodes.at(0)],
        queueItems = nodes.map(function (item) {
          return {
            name: '',
            state: 'rejected',
            errorMessage: errorMessage,
            count: 1,
            total: 1,
            node: item
          };
        });
      var nodeCollection = new UploadFileCollection(queueItems, {connector: node.connector});
      nodeCollection.each(function (item) {
        item.node = item.get('node');
        item.unset('node');
      });

      GlobalMessage.showProgressPanel(nodeCollection, {
        oneFileFailure: _.str.sformat(lang.MassUpdateFailureMessage, configName)
      });
    },

    _executeMassUpdate: function (status, options) {
      var me = this;

      _.extend(options, status);

      options.selectionHasFiles = _.contains(options.nodes.pluck('type'), 144);
      options.selectionHasFolders = _.contains(options.nodes.pluck('type'), 0) || _.contains(options.nodes.pluck('type'), 142); // folder or cabinet
      options.selectionHasVD = _.contains(options.nodes.pluck('r_is_virtual_doc'), 1);

      var node = CommandHelper.getAtLeastOneNode(status).first();

      me._blockActions(status.originatingView);
      return this._fetchMassupdateConfig(node, options).then(function (config) {
        options.massUpdateConfig = config;
        if (!config.links) {
          //TODO: Better to pass this message in reject and let the messaging be handled all in one place
          GlobalMessage.showMessage('error', lang.MassUpdateConfigNotFound);
          return $.Deferred().reject().promise();
        } else {
          me._unblockActions(status.originatingView);
          _.extend(options, config);
          return me._showOptionsDialog(options);
        }
      }).then(function (optionsData) {
        _.extend(options, optionsData, {"signature": me.get('signature')});
        return me._validateAndLaunchWizard(options);
      });
    },

    _validateAndLaunchWizard: function (options) {
      var deferred = $.Deferred(),
        me = this;
      options.massUpdateData = {};
      options.massUpdateConfigName = options['massupdate_config_label'] || options['massupdate_config_name'];
      csui.require([
        'd2/dialogs/mass.update/mass.update.dialog'
      ], function (MassUpdateDialog) {
        var massUpdateDialog = new MassUpdateDialog({
          context: options.context,
          massUpdateConfig: options.massUpdateConfig,
          updateTypes: options['update-types'],
          commandOptions: options,
          massUpdateValidationPromise: me._initiateValidationOnSelectedItems(options)
        });
        massUpdateDialog.showMassUpdateWizard().done(deferred.resolve).fail(deferred.reject);
      });
      return deferred.promise();
    },

    _blockActions: function (view) {
      CommandHelper.blockD2ViewActions(view);
    },

    _unblockActions: function (view) {
      CommandHelper.unblockD2ViewActions(view);
    },

    _initiateValidationOnSelectedItems: function (options) {
      var url = RestLinkrels.getLink(options.links, RestLinkrels.D2_MASS_UPDATE_OBJECT_VALIDATION),
        urlParams = {},
        connector;

      if (options['update-types'] === constants.MassUpdateOptions.FILE_PROPERTIES) {
        _.extend(urlParams, {
          'include-subfolder': _.contains(options['include-options'], constants.MassUpdateOptions.FILES_IN_SUB_FOLDERS),
          'include-vd-descendants': _.contains(options['include-options'], constants.MassUpdateOptions.VIRTUAL_DOCUMENTS_DESCENDANTS),
          'include-all-versions': _.contains(options['include-options'], constants.MassUpdateOptions.ALL_VERSIONS),
          'update-type': 'FILE'
        });
      } else if (options['update-types'] === constants.MassUpdateOptions.FOLDER_PROPERTIES) {
        _.extend(urlParams, {
          'include-subfolder': _.contains(options['include-options'], constants.MassUpdateOptions.SUB_FOLDERS),
          'update-type': 'FOLDER'
        });
      } else if ((options.selectionHasFiles && !options.selectionHasFolders && !options.selectionHasVD)) {
        options['include-options'] = [];
        options['update-types'] = constants.MassUpdateOptions.FILE_PROPERTIES;
        options['include_all_versions'] && options['include-options'].push(constants.MassUpdateOptions.ALL_VERSIONS);
      }

      url = Url.appendQuery(url, Url.combineQueryString(urlParams));
      connector = options.context.getObject(ConnectorFactory);
      return $.ajax(connector.extendAjaxOptions({
        url: url,
        type: 'POST',
        contentType: constants.MediaTypes.DCTM_JSON,
        dataType: 'json',
        data: JSON.stringify({'object-ids': options.nodes.pluck('id')})
      }));
    },

    refreshNodes: function (status, data) {
      var me = this,
        deferred = $.Deferred(),
        massUpdateValidNodesMap = data.massUpdateValidNodes && _.reduce(data.massUpdateValidNodes, function (map, massUpdateNode) {
          var id = massUpdateNode['r_object_id'];
          map[id] = massUpdateNode;
          return map;
        }, {}),
        nodes = status.nodes.filter(function (node) {
          var id = node.get('id');
          return (massUpdateValidNodesMap && !!massUpdateValidNodesMap[id]);
        }),
        collection = status.collection || status.originatingView.collection,
        widgetType = collection && collection.widgetType,
        widgetName = collection && collection.options && collection.options.widgetName;

      function performSingleNodeRefresh(node) {
        var refreshOptions = {};
        if (widgetName && widgetType) {
          refreshOptions.widgetType = widgetType;
          refreshOptions.widgetName = widgetName;
          refreshOptions.isDisableLocationColumn = collection.options.isDisableLocationColumn;
        }
        return CommandHelper.refreshNode(node, refreshOptions);
      }

      function performMultipleNodeRefresh(nodes) {
        var dfd = $.Deferred(),
          taskQueue = new TaskQueue({
            parallelism: 3
          }),
          promises = [];

        _.each(nodes, function (node) {
          var promise = $.Deferred();
          promises.push(promise);
          taskQueue.pending.add({
            worker: function () {
              performSingleNodeRefresh(node).always(function () {
                promise.resolve();
              });
              return promise.promise();
            }
          });
        });
        $.whenAll.apply($, promises).always(function () {
          dfd.resolve();
        });
        return dfd.promise();
      }

      if (nodes.length === 1) {
        me._blockActions(status.originatingView);
        performSingleNodeRefresh(nodes[0]).always(function () {
          me._unblockActions(status.originatingView);
          deferred.resolve();
        });
      } else if (nodes.length > 1) {
        me._blockActions(status.originatingView);
        CommandHelper.refreshNodes(nodes, {
          connector: status.context.getObject(ConnectorFactory),
          widgetType: widgetType,
          widgetName: widgetName,
          collection: collection,
          selectedNodes: status.d2SelectedNodes || status.nodes
        }).done(function (data) {
          if (data && data.nodesRefreshed === true) {
            me._unblockActions(status.originatingView);
            deferred.resolve();
          } else {
            performMultipleNodeRefresh(nodes).always(function () {
              me._unblockActions(status.originatingView);
              deferred.resolve();
            });
          }
        }).fail(function () {
          me._unblockActions(status.originatingView);
          deferred.reject();
        });
      } else {
        deferred.resolve();
      }
      return deferred.promise();
    }
  });
});

csui.define('d2/commands/show.dialog',[
  'require',
  'nuc/lib/jquery',
  'nuc/lib/underscore',
  'nuc/lib/backbone',
  'nuc/models/nodes',
  'csui/models/command',
  'csui/utils/commandhelper',
  'd2/utils/constants',
  'dctmw/utils/rest.resources',
  'i18n!d2/commands/nls/localized.strings'
], function(require, $, _, Backbone, NodeCollection, CommandModel, CommandHelper, constants, RestResources, lang){
  'use strict';

  const ShowDialog = CommandModel.extend({
    defaults: {
      signature: 'D2-ShowDialog',
      command_key: 'D2-ShowDialog',
      name: lang.CommandShowDialog,
      scope: 'multiple'
    },

    enabled: function(status, options) {
      let menuType;
      if (status.toolItem) {
        let props = status.toolItem.get('actionProperties');
        menuType = props && props.menuType;
      }
      if(menuType === constants.MenuTypes.USER) {
        let userMenuActions = RestResources.getCurrentUser().get('MenuActions');
        if(userMenuActions instanceof Backbone.Collection) {
          return !!userMenuActions.get(this.get('signature'));
        }
      } else if(menuType === constants.MenuTypes.NEW_OBJECT) {
        if (status.container) {
          let nodes = new NodeCollection([status.container]),
            newStatus = _.defaults({nodes: nodes}, status);
          return ShowDialog.__super__.enabled.call(this, newStatus, options);
        } else {
          console.warn('status.container not defined.');
        }
      }
      return ShowDialog.__super__.enabled.call(this, status, options);
    },

    execute: function(status/*, options*/) {
      let dfd = $.Deferred(),
        nodes = CommandHelper.getAtLeastOneNode(status),
        applicableNodes = nodes && nodes.length ? ( status.data.raw === 'true' ? [...nodes.models] : [nodes.at(0)]) : [];

      status.suppressSuccessMessage = true;
      status.suppressFailureMessage = true;

      csui.require([
        'd2/dialogs/generic/dynamic.dialog'
      ], function(DynamicDialog){
        const dialog = new DynamicDialog({
          nodes: new NodeCollection(applicableNodes),
          data: _.omit(status?.data, 'menuId'),
          viewMode: status?.data?.viewMode || constants.WizardType.DIALOG,
          context: status.context,
          collection: status.collection,
          originatingView: status.originatingView
        });
        dialog.show(status?.data?.DIALOG_NAME).on('wizard:closed', dfd.resolve);
      }, dfd.reject);

      return dfd.promise();
    }
  });

  return ShowDialog;
});


csui.define('css!d2/commands/aviator/impl/launch.aviator.chat',[],function(){});

csui.define('d2/commands/aviator/launch.aviator.chat',[
    'require',
    'nuc/lib/jquery',
    'nuc/lib/underscore',
    'nuc/lib/backbone',
    'csui/models/command',
    'csui/utils/commandhelper',
    'd2/utils/node.utils',
    'dctmw/utils/authenticators/session',
    'i18n!d2/commands/nls/localized.strings',
    'css!d2/commands/aviator/impl/launch.aviator.chat'
], function (require, $, _, Backbone, CommandModel, CommandHelper, nodeUtils, Session, lang) {
    'use strict';

    const AVIATOR_CHAT_VIEWER_COMBINE_WIDTH = 1280;

    const LaunchAviatorChatCommand = CommandModel.extend({
        defaults: {
            signature: 'Aviator-LaunchChat',
            command_key: 'Aviator-LaunchChat',
            name: lang.CommandLaunchAviatorChat,
            scope: 'single'
        },

        enabled: function (status, options) {
            let enabled = false;
            if (status) {
                if (status.nodes && status.nodes.length > 0) {
                    enabled = CommandModel.prototype.enabled.call(this, status, options);
                } else if (status.container) {
                    //This block is added for showing Aviator action in table header
                    enabled = CommandModel.prototype.enabled.call(this, {
                        toolItem: status.toolItem,
                        nodes: new Backbone.Collection([status.container])
                    });
                }
            }
            return enabled;
        },

        execute: function (status, options) {
            let dfd = $.Deferred(),
                context = status.context ?? options?.context,
                node = CommandHelper.getJustOneNode(status);

            if (!node && status.container) {
                node = status.container
            }

            status.suppressSuccessMessage = true;
            status.suppressFailMessage = true;
            this.openAviatorChatDialog(context, node).done(dfd.resolve);
            return dfd.promise();
        },

        openAviatorChatDialog: function (context, node) {
            let dfd = $.Deferred();
            csui.require(['aie/controls/chat.panel/chat.panel.view', 'css!aie/commands/aviator/impl/aviator'], (ChatPanelView) => {
                let chatPanel = new ChatPanelView({
                    context,
                    node
                });
                this.enableViewerIfApplicable(chatPanel, node, context).done(dfd.resolve.bind(dfd, chatPanel));
                chatPanel.listenTo(Session.get(), 'end', chatPanel.hide);
                chatPanel.show();
            });
            return dfd.promise();
        },

        enableViewerIfApplicable: function (chatPanel, node, context) {
            let dfd = $.Deferred();
            if (nodeUtils._showViewer(node)) {
                chatPanel.once('after:show', () => {
                    if (window.innerWidth >= AVIATOR_CHAT_VIEWER_COMBINE_WIDTH) {
                        this.showViewerInAviatorPanel.call(this, chatPanel, node, context).done(dfd.resolve);
                    } else {
                        dfd.resolve();
                    }
                });
            } else {
                dfd.resolve();
            }
            return dfd.promise();
        },

        showViewerInAviatorPanel: function (chatPanel, node, context) {
            let dfd = $.Deferred();
            csui.require(['d2/widgets/miniviewer/miniviewer.view'], (ViewerView) => {
                let $viewerEl = $('<div>', {
                        class: 'aie-viewer d2-aie-viewer',
                    }),
                    viewerNode = node.clone();
                $viewerEl.insertBefore(chatPanel.$el.find('.csui-sidepanel-container'));
                viewerNode.fetched = true;
                let viewerView = new ViewerView(
                    _.defaults({
                        el: $viewerEl[0],
                        model: viewerNode,
                        context: context,
                        isAnnotationDisable: true
                    })
                );
                viewerView.render();
                viewerView.model.trigger('sync');
                viewerView.once('destroy', () => {
                    $viewerEl.remove();
                });
                viewerView.once('viewer:close', viewerView.destroy);
                chatPanel.once('before:hide', viewerView.destroy);
                dfd.resolve();
            });
            return dfd.promise();
        }
    });

    return LaunchAviatorChatCommand;
});

