csui.define('d2/commands/open.plugins/impl/publish/publish.dialog.body.view',[
  'nuc/lib/jquery',
  'nuc/lib/underscore',
  'nuc/lib/marionette',
  'csui/models/form',
  'd2/widgets/metadata/utils/form.converter',
  'd2/controls/form/d2.form.view',
  'd2/controls/behaviors/wizard.tabable.region.behavior',
  'csui/controls/tile/behaviors/perfect.scrolling.behavior',
  'd2/commands/open.plugins/impl/publish/publish.fields.constant',
  'i18n!d2/commands/open.plugins/nls/localized.strings',
  'i18n!d2/dialogs/add.version/impl/nls/lang'
], function ($, _, Marionette, FormModel, MetadataConverter, D2FormView,
             WizardTabableRegionBehavior, PerfectScrollingBehavior, PublishFieldsConstant, lang, addVersionLang) {
  'use strict';

  return D2FormView.extend({

    constructor: function PublishDialogBodyView(options) {
      this.options = options || {};

      this.formRendered = false;

      var dialog = this._createDialogJson();
      var me = this;
      this.formmodel = MetadataConverter.convertConfig(dialog, {
        actionMode: 'create',
        layoutMode: 'singleCol',
        extendFieldOptions: function (field, alpControl) {
          if (field && alpControl) {
            var fieldId = field.id;
            if (fieldId === 'folder-id') {
              _.extend(alpControl['options']['fields'][fieldId], {
                subTypeFilters: ["dm_folder"],
                container: me.options.container
              });
            }
          }
        }
      });
      options.model = new FormModel(this.formmodel.propertiesConfig[0]);

      this._setExpressions();
      options.topAlignedLabel = true;
      options.mode = 'create';

      _.extend(this.behaviors, {
        PerfectScrolling: {
          behaviorClass: PerfectScrollingBehavior,
          suppressScrollX: true,
          scrollYMarginOffset: 15
        },
        WizardTabableRegionBehavior: {
          behaviorClass: WizardTabableRegionBehavior
        }
      });
      D2FormView.prototype.constructor.call(this, options);
    },

    className: function () {
      var parentClassName = D2FormView.prototype.className || '';
      if (_.isFunction(parentClassName)) {
        parentClassName = parentClassName.apply(this, arguments);
      }
      return parentClassName + ' d2-publish-dialog-body';
    },

    _setExpressions: function () {
      if (this.options.checkinConfig && this.options.addExtraOptions && _.contains(this.options.addExtraOptions, PublishFieldsConstant.publishOptions.VERSION)) {
        this.options.model.attributes.expressions['checkin_version']['setVisible'] = "(getValue(publish_options).equals('version'))";
      }
      if (!this.options.checkinConfig && this.options.addExtraOptions && _.contains(this.options.addExtraOptions, PublishFieldsConstant.publishOptions.VERSION)) {
        this.options.model.attributes.expressions['version_error_field']['setVisible'] = "(getValue(publish_options).equals('version'))";
      }
      this.options.model.attributes.expressions['folder-id']['setVisible'] = "(getValue(publish_options).equals('browse'))";
      this.options.model.attributes.expressions['input-file-name']['setVisible'] = "(getValue(publish_options).equals('browse') || getValue(publish_options).equals('home-cabinet') || getValue(publish_options).equals('current-location'))";
    },

    _createDialogJson: function () {
      var form = {
        order: 1,
        "combo": {
          "id": PublishFieldsConstant.publishFields.OPTIONS,
          "type": "combo",
          "label": lang.PublishDialogFieldsOptionsLabel,
          "order": "1.1",
          "isEditable": false,
          "removeDefaultNone": true,
          "condition_required": true,
          "condition_enabled": true,
          "condition_visible": true,
          "o": [
            {
              "is-default": false,
              value: PublishFieldsConstant.publishOptions.BROWSE,
              text: lang.PublishDialogOptionsBrowseText
            },
            {
              "is-default": false,
              value: PublishFieldsConstant.publishOptions.HOME_CABINET,
              text: lang.PublishDialogOptionsHomeCabinetText
            }
          ]
        },
        "node-picker": [{
          order: "1.2",
          id: PublishFieldsConstant.publishFields.FOLDER,
          label: lang.PublishDialogFieldsFolderLabel,
          condition_required: true,
          property_type: "string",
          repeating: false
        }],
        "text": [{
          "id": PublishFieldsConstant.publishFields.FILE_NAME,
          "type": "text",
          label: lang.PublishDialogFieldsFileNameLabel,
          order: 1.3,
          condition_required: true,
          value: this.options.defaultFileName
        }]
      };

      if (this.options.addExtraOptions && _.contains(this.options.addExtraOptions, PublishFieldsConstant.publishOptions.CURRENT_LOCATION)) {
        form.combo.o.splice(0, 0, {
          "is-default": false,
          value: PublishFieldsConstant.publishOptions.CURRENT_LOCATION,
          text: lang.PublishDialogOptionsCurrentLocationText
        });
      }

      if (this.options.addExtraOptions && _.contains(this.options.addExtraOptions, PublishFieldsConstant.publishOptions.RENDITION)) {
        form.combo.o.push({
          "is-default": false,
          value: PublishFieldsConstant.publishOptions.RENDITION,
          text: lang.PublishDialogOptionsRenditionText
        });
      }

      if (this.options.addExtraOptions && _.contains(this.options.addExtraOptions, PublishFieldsConstant.publishOptions.VERSION)) {
        form.combo.o.push({
          "is-default": false,
          value: PublishFieldsConstant.publishOptions.VERSION,
          text: lang.PublishDialogOptionsVersionText
        });
      }

      form.combo.o.push({
        "is-default": false,
        value: PublishFieldsConstant.publishOptions.DOWNLOAD,
        text: lang.PublishDialogOptionsDownloadText
      });

      form.combo.o[0]['s'] = true;

      if (this.options.checkinConfig &&
        this.options.addExtraOptions && _.contains(this.options.addExtraOptions, PublishFieldsConstant.publishOptions.VERSION)) {
        var selected = _.find(this.options.checkinConfig['checkin-version-options'], {selected: true});
        var versionLabels = this.options.node.get('r_version_label');
        this.options.checkinConfig['checkin-version-options'].map(function (item, index) {
          item.s = (!selected && index === 0) ? true : item.selected;
          item.l = item.version;
          if (_.contains(versionLabels, item.version)) {
            item.l = _.str.sformat(addVersionLang.Replace, item.version);
          }
          item.v = item['version_policy'];
        });
        form['list-radio'] = {
          id: PublishFieldsConstant.publishFields.VERSION,
          type: "list-radio",
          label: lang.PublishDialogFieldsVersionLabel,
          order: "1.4",
          /*condition_visible: false,*/
          visible: false,
          condition_required: false,
          vertical: true,
          o: this.options.checkinConfig['checkin-version-options']
        };
      }

      if (!this.options.checkinConfig) {
        form["html-editor"] = {
          "id": 'version_error_field',
          "type": "html-editor",
          label: '',
          condition_visible: false,
          condition_required: false,
          order: 1.5,
          value: this.options.reserveFileError
        };
      }

      return {
        dialog: {
          content: form
        }
      };
    },

    onRender: function () {
      this.formRendered = true;
    },

    isFormRendered: function () {
      return this.formRendered;
    }
  });

});


csui.define('css!d2/commands/open.plugins/impl/publish/publish.dialog',[],function(){});

csui.define('d2/commands/open.plugins/impl/publish/publish.dialog',[
  'nuc/lib/jquery',
  'nuc/lib/underscore',
  'nuc/lib/marionette',
  'nuc/models/node/node.model',
  'nuc/models/nodes',
  'nuc/utils/url',
  'csui/utils/contexts/factories/connector',
  'csui/utils/commandhelper',
  'csui/controls/dialog/dialog.view',
  'd2/controls/globalmessage/globalmessage',
  'd2/utils/rest.linkrels',
  'd2/utils/constants',
  'dctmw/utils/utils',
  'dctmw/utils/rest.resources',
  'd2/commands/reserve',
  'd2/commands/unreserve',
  'd2/controls/globalmessage/impl/progresspanel/node.creation.success.message.view',
  'd2/commands/open.plugins/impl/publish/publish.dialog.body.view',
  'd2/commands/open.plugins/impl/publish/publish.fields.constant',
  'i18n!d2/commands/open.plugins/nls/localized.strings',
  'css!d2/commands/open.plugins/impl/publish/publish.dialog'
], function ($, _, Marionette, NodeModel, NodeCollection, Url, ConnectorFactory, CommandHelper, DialogView, GlobalMessage,
             RestLinkrels, constants, utils, RestResources, ReserveCommand, UnReserveCommand,
             NodeCreationSuccessMessageView, DialogBodyView, PublishFieldsConstant, lang) {
  'use strict';

  var dialogAlreadyOpen = false;

  var publishDialog = Marionette.Object.extend({
    initialize: function (options) {
      this.saveButtonId = 'publish-save';
      this.options = options;
      this.node = this.options.node.clone();
      this.container = this.node.parent;
      this._connector = this.options.context.getObject(ConnectorFactory);
    },

    show: function () {
      if(dialogAlreadyOpen) {
        return;
      }
      dialogAlreadyOpen = true;
      var me = this, deferred = $.Deferred();
      var currentUser = RestResources.getCurrentUser();
      if (currentUser && currentUser.attributes && currentUser.attributes.properties &&
        currentUser.attributes.properties.client_capability === 1) {
        this.downloadAction();
        return deferred.resolve().promise();
      }
      this._blockActions();
      this.container.fetch().done(function () {
        me.filterVersionAndRenditionPermission().done(function (filtered) {
          me.options.addExtraOptions = filtered;
          if (_.contains(me.options.addExtraOptions, PublishFieldsConstant.publishOptions.VERSION)) {
            me._reserveFile(me.node).done(function () {
              me.fetchCheckInConfig(me.options.node).done(function (checkinconfig) {
                me.setCheckinConfig(checkinconfig);
                var dialog = me.showDialog(checkinconfig);
                me._unblockActions();
                deferred.resolve({dialog: dialog});
              }).fail(function (error) {
                me._unblockActions();
                deferred.reject(error);
              });
            }).fail(function (error) {
              me.reserveFileError = error[0]['message'];
              var dialog = me.showDialog();
              me._unblockActions();
              deferred.resolve({dialog: dialog});
            });
          } else {
            var dialog = me.showDialog();
            me._unblockActions();
            deferred.resolve({dialog: dialog});
          }
        });
      });

      return deferred.promise();
    },

    filterVersionAndRenditionPermission: function () {
      var me = this, deferred = $.Deferred();
      var versionPreCheckUrl = this.getPreCheckLink(this.node);
      this.getPermission().done(function (response) {
        var filtered = me.options.addExtraOptions.filter(function (value/*, index, arr*/) {
          if (value === PublishFieldsConstant.publishOptions.VERSION &&
            !versionPreCheckUrl) {
            return false;
          } else if (value === PublishFieldsConstant.publishOptions.RENDITION &&
            !_.contains(['Delete', 'Write'], response['basic-permission'])) {
            return false;
          } else {
            return true;
          }
        });
        deferred.resolve(filtered);
      });
      return deferred.promise();
    },

    getPermission: function () {
      var url = RestLinkrels.getLink(this.node.get('links'), RestLinkrels.D2_OBJECT_PERMISSIONS);
      return $.ajax(this._connector.extendAjaxOptions({
        url: url,
        method: 'GET'
      }));
    },

    showDialog: function (checkinConfig) {
      var me = this;
      this.dialogBodyView = new DialogBodyView({
        node: this.options.node,
        checkinConfig: checkinConfig,
        context: this.options.context,
        addExtraOptions: this.options.addExtraOptions,
        reserveFileError: this.reserveFileError,
        container: this.container,
        defaultFileName: this.options.defaultFileName
      });
      this.dialog = new DialogView({
        title: lang.PublishDialogTitle,
        iconLeft: 'csui-icon-notification-confirmation-white',
        view: this.dialogBodyView,
        className: "d2-publish-dialog",
        midSize: true,
        buttons: [
          {
            id: this.saveButtonId,
            label: lang.SaveButtonText,
            'default': true,
            disabled: true,
            click: function (/*args*/) {
              me.saveDialog();
            }.bind(this),
          },
          {
            label: lang.CancelButtonText,
            close: true
          }
        ]
      });

      this.dialog.listenTo(this.dialog, 'hide', _.bind(this.onHideDialog, this));
      this.dialog.listenToOnce(this.dialog, 'after:show', me.onDialogShown());
      this.listenTo(this.dialogBodyView, 'change:field', me.updateForm.bind(this));

      this.listenTo(this.dialogBodyView, 'valid:field', this.validateAndUpdateFooterButton.bind(this));
      this.listenTo(this.dialogBodyView, 'invalid:field', this.validateAndUpdateFooterButton.bind(this));
      this.listenTo(this.dialogBodyView, 'render', this.validateAndUpdateFooterButton.bind(this));

      this.dialog.show();

      return this.dialog;
    },

    updateForm: function (event) {
      if (event.targetField.name === PublishFieldsConstant.publishFields.OPTIONS &&
        event.targetField.value === PublishFieldsConstant.publishOptions.DOWNLOAD) {
        this.updateButtonText(this.saveButtonId, lang.DownloadButtonText);
      } else {
        this.updateButtonText(this.saveButtonId, lang.SaveButtonText);
      }
    },

    validateAndUpdateFooterButton: function () {
      this.dialogBodyView.validateForm(false, false).done(function (isValid) {
        if(isValid) {
          $(this.dialog.footerView.el).find('#'+this.saveButtonId).removeAttr("disabled");
        } else {
          $(this.dialog.footerView.el).find('#'+this.saveButtonId).attr("disabled", "true");
        }

      }.bind(this));
    },


    updateButtonText: function (id, text) {
      var button = this.dialog.footerView.collection.get(id);
      if (button) {
        var buttonView = this.dialog.footerView.children.findByModel(button);
        $(buttonView.el).text(text);
      }
    },

    onHideDialog: function () {
      dialogAlreadyOpen = false;
      if (this.options.node && this.reserved) {
        this._unReserveFile(this.node);
      }
    },

    saveDialog: function () {
      var me = this, formValues = this.dialogBodyView.form.getValue();

      if (formValues[PublishFieldsConstant.publishFields.OPTIONS] === PublishFieldsConstant.publishOptions.HOME_CABINET ||
        formValues[PublishFieldsConstant.publishFields.OPTIONS] === PublishFieldsConstant.publishOptions.CURRENT_LOCATION ||
        formValues[PublishFieldsConstant.publishFields.OPTIONS] === PublishFieldsConstant.publishOptions.BROWSE) {
        var currentLocation = (formValues[PublishFieldsConstant.publishFields.OPTIONS] === PublishFieldsConstant.publishOptions.CURRENT_LOCATION) ? true : false;
        this.saveToDocBase(currentLocation).done(function (response) {
          me.showSuccessMessage(response);
        }).fail(function (/*error*/) {
          me.dialog.kill();
          GlobalMessage.showMessage('error', lang.PublishErrorMessage);
        });
      }
      if (formValues[PublishFieldsConstant.publishFields.OPTIONS] === PublishFieldsConstant.publishOptions.VERSION) {
        this.saveVersion().done(function (response) {
          var responseJson = JSON.parse(response);
          var versionObj = _.findWhere(me.checkinConfig["checkin-version-options"], {"version": responseJson.version});
          var successMessage = _.str.sformat(lang.PublishVersionSuccessMessage, responseJson.version, me.node.get("name"));
          if (versionObj && versionObj.version_policy === 2) { //Replace
            successMessage = _.str.sformat(lang.PublishVersionReplaceSuccessMessage, me.node.get("name"));
          }
          GlobalMessage.showMessage('success', successMessage);
        }).fail(function (/*error*/) {
          GlobalMessage.showMessage('error', lang.PublishErrorMessage);
        }).always(function () {
          me.dialog.kill();
        });
      }
      if (formValues[PublishFieldsConstant.publishFields.OPTIONS] === PublishFieldsConstant.publishOptions.RENDITION) {
        this.createRendition().done(function (/*response*/) {
          GlobalMessage.showMessage('success', lang.PublishRenditionSuccessMessage);
        }).fail(function (error) {
          var errorMessage = lang.PublishRenditionExistsMessage;
          if (error.status !== 503) {
            errorMessage = lang.PublishErrorMessage;
          }
          GlobalMessage.showMessage('error', errorMessage);
        }).always(function () {
          me.dialog.kill();
        });

      }
      if (formValues[PublishFieldsConstant.publishFields.OPTIONS] === PublishFieldsConstant.publishOptions.DOWNLOAD) {
        this.downloadAction();
        this.dialog.kill();
      }
    },

    showSuccessMessage: function (response) {
      var me = this, newNode, responseJson = JSON.parse(response);
      this._blockActions();
      newNode = this.getNodeModel(responseJson.r_object_id);
      newNode.fetch().done(function () {
        var successMessage = _.str.sformat(lang.PublishNewDocumentSuccessMessage, newNode.get("name"));
        if (me.container.get("id") === newNode.parent.get("id")) {
          GlobalMessage.showMessage("success", successMessage);
          me._unblockActions();
          me.dialog.kill();
        } else {
          var newNodeLocation = newNode.parent;
          newNodeLocation.fetch().done(function () {
            me.showSuccessMessageWithLocation(newNodeLocation, successMessage, me.options.context, true);
            me._unblockActions();
            me.dialog.kill();
          });
        }
      });
    },

    getNodeModel: function (docId) {
      return new NodeModel({id: docId}, {connector: this._connector});
    },

    showSuccessMessageWithLocation: function (node, msg, context, showLink) {
      GlobalMessage._showMessageView(NodeCreationSuccessMessageView, {
        showLink: showLink,
        node: node,
        context: context,
        successMessageFormat: msg,
        linkLabel: lang.PublishGoToLocation,
        link_command_signature: 'Browse'
      });
    },

    downloadAction: function () {
      var link = document.createElement("a");
      link.setAttribute('download', '');
      link.setAttribute('target', '_blank');
      link.href = this.options.publishUrl;
      document.body.appendChild(link);
      link.click();
      link.remove();
    },

    saveToDocBase: function (currentLocation) {
      var url,
        formValues = this.dialogBodyView.form.getValue(), location,
        currentRepo = RestResources.getCurrentRepository().get('name');

      var param = {
        "publishurl": this.options.publishUrl,
        "filename": formValues[PublishFieldsConstant.publishFields.FILE_NAME],
        "format": this.options.type,
        "action": 'docbase'
      };

      if (currentLocation) {
        location = this.node.parent.get("id");
      } else {
        location = formValues[PublishFieldsConstant.publishFields.FOLDER];
      }

      if (formValues[PublishFieldsConstant.publishFields.OPTIONS] === PublishFieldsConstant.publishOptions.HOME_CABINET) {
        param['action'] = "homecabinet";
      } else {
        param["location"] = location;
      }

      url = Url.combine(this._connector.connection.url, "repositories", currentRepo, "bravaenterprise", "publish");

      return $.ajax(this._connector.extendAjaxOptions({
        url: url,
        method: 'GET',
        data: param,
      }));
    },

    saveVersion: function () {
      var url,
        formValues = this.dialogBodyView.form.getValue(),
        currentRepo = RestResources.getCurrentRepository().get('name'),
        checkinVersion = formValues[PublishFieldsConstant.publishFields.VERSION],
        action = (checkinVersion === 1) ? 'minorversion' : 'majorversion';

      if (checkinVersion === 2) {
        action = 'sameversion';
      }

      url = Url.combine(this._connector.connection.url, "repositories", currentRepo, "bravaenterprise", "publish");

      var param = {
        "publishurl": this.options.publishUrl,
        "filename": this.node.get("name"),
        "format": this.options.type,
        "docId": this.node.get("id"),
        "action": action
      };

      return $.ajax(this._connector.extendAjaxOptions({
        url: url,
        method: 'GET',
        data: param
      }));
    },

    createRendition: function () {
      var url,
        currentRepo = RestResources.getCurrentRepository().get('name');

      url = Url.combine(this._connector.connection.url, "repositories", currentRepo, "bravaenterprise", "publish");

      var param = {
        "publishurl": this.options.publishUrl,
        "filename": this.node.get("name"),
        "format": this.options.type,
        "docId": this.node.get("id"),
        "action": 'rendition'
      };

      return $.ajax(this._connector.extendAjaxOptions({
        url: url,
        method: 'GET',
        data: param
      }));
    },

    onDialogShown: function () {
      var me = this;
      var resizeFn = _.bind(me._doResize, me);

      setTimeout(function () {
        resizeFn();
      }, 500);
    },

    _doResize: function () {
      var newHeight = this.dialog.$el.find('.binf-modal-content').outerHeight(true);
      this.dialog.$el.find('.binf-modal-dialog').css('margin-top', ((this.dialog.$el.height() - newHeight) / 2) + 'px');
    },

    setCheckinConfig: function (checkinconfig) {
      this.checkinConfig = checkinconfig;
    },

    fetchCheckInConfig: function (node) {
      var deferred = $.Deferred(),
        href = this.getCheckinConfigLink(node);
      if (!href) {
        deferred.reject(new Error("need to check for config url"));
      } else {
        $.ajax(node.connector.extendAjaxOptions({
          url: href,
          headers: {
            'Content-Type': constants.MediaTypes.DCTM_JSON
          },
          success: function (response) {
            deferred.resolve(response);
          },
          error: function (xhr) {
            var errorDetails = utils.parseAjaxError(xhr);
            deferred.reject(errorDetails);
          }
        }));
      }
      return deferred.promise();
    },

    _reserveFile: function (node) {
      var me = this, deferred = $.Deferred(), reserveCommand = new ReserveCommand(),
        precheckurl = this.getPreCheckLink(node), precheckUrlMap = {};

      precheckUrlMap[node.get('id')] = precheckurl;
      var status = {
        nodes: new NodeCollection([node]),
        context: this.options.context
      };
      var reserveoptions = _.defaults({
        ignoreDownload: true,
        suppressProgress: true,
        hideSuccessMessage: true,
        hideFailureMessage: true,
        precheckUrlMap: precheckUrlMap,
        suppressConfirmationDialog: true,
      }, this.options);

      reserveCommand.execute(status, reserveoptions).done(function (nodes) {
        me.reserved = true;
        status.nodes.set(nodes);
        deferred.resolve();
      }).fail(function (error) {
        deferred.reject(error);
      });
      return deferred.promise();
    },

    _unReserveFile: function (node) {
      var deferred = $.Deferred(),
        status = {
          nodes: new NodeCollection([node]),
          context: this.options.context
        };
      if (this.reserved) {
        var unreserveCommand = new UnReserveCommand();
        unreserveCommand.execute(status, {
          suppressProgress: true,
          hideSuccessMessage: true,
          hideFailureMessage: true
        }).always(function () {
          deferred.resolve();
        });
      } else {
        deferred.resolve();
      }
      return deferred.promise();
    },

    getCheckinConfigLink: function (node) {
      return CommandHelper.getOriginalActionLink(node, 'AddVersion', RestLinkrels.D2_CHECKIN_CONFIG);
    },

    getPreCheckLink: function (node) {
      return CommandHelper.getOriginalActionLink(node, 'AddVersion', RestLinkrels.CHECKOUT_PRECHECK);
    },

    _blockActions: function (/*status*/) {
      $('div.load-container.csui-global').removeClass('binf-hidden');
    },

    _unblockActions: function (/*status*/) {
      $('div.load-container.csui-global').addClass('binf-hidden');
    }

  });

  return publishDialog;
});

csui.define('css!d2/commands/open.plugins/impl/bravaenterpriseviewer',[],function(){});

csui.define('d2/commands/open.plugins/impl/bravaenterpriseviewer.view',[
  'module',
  'require',
  'nuc/lib/underscore',
  'nuc/lib/jquery',
  'nuc/lib/marionette',
  'smart/utils/accessibility',
  'csui/utils/contexts/factories/node',
  'dctmw/utils/rest.resources',
  'nuc/utils/url',
  'd2/controls/behaviors/viewer.masking.behavior',
  'csui/dialogs/modal.alert/modal.alert',
  'd2/commands/open.plugins/impl/markup.migration/view',
  'd2/commands/open.plugins/impl/publish/publish.fields.constant',
  'i18n',
  'd2/commands/open.plugins/impl/bravaenterprise/viewer.utils',
  'd2/utils/format.utils',
  'i18n!d2/commands/open.plugins/nls/localized.strings',
  'd2/commands/open.plugins/impl/publish/publish.dialog',
  'd2/commands/open.plugins/impl/iviewer/utils',
  'd2/commands/download',
  'd2/utils/rest.linkrels',
  'css!d2/commands/open.plugins/impl/bravaenterpriseviewer'
], function (module, require, _, $, Marionette, Accessibility, NodeModelFactory, RestResources, Url, ViewerMaskingBehavior,
             ModalAlert, markupMigrationView, PublishFieldsConstant, i18n, ViewerUtils, FormatUtils, lang, PublishDialog,
             iViewerUtils, DownloadCommand, RestLinkrels) {
  'use strict';

  var moduleConfig = _.defaults(module.config(), {
    basePath: window.sv.config.releaseLocation + window.sv.config.otherBundlesLocation
  });

  var BravaEnterpriseView = Marionette.ItemView.extend({
    className: 'd2-bravaenterpriseviewer',

    template: _.template('<div id="migrationInfo" class="migration-info binf-hidden"></div>'),

    behaviors: {
      MaskingBehavior: {
        behaviorClass: ViewerMaskingBehavior
      }
    },

    constructor: function BravaEnterpriseView(options) {
      options.data || (options.data = {});

      if (options.collection) {
        throw 'Collection viewing is not supported yet.';
      }

      if (!options.model) {
        options.model = options.context.getModel(NodeModelFactory, {
          attributes: {
            id: options.data.id,
            version_number: options.data.version_number || undefined
          }
        });
      }

      Marionette.ItemView.prototype.constructor.call(this, options);

      this._connector = this.model.connector;
      this.isPreviewMode = options.isPreviewMode;
      this.isEmbeddedPreview = options.isEmbeddedPreview ? options.isEmbeddedPreview : false;
      this.isExpanded = false;
      this.expandButtonTooltip = lang.ButtonExpandViewer;
      this.collapseButtonTooltip = lang.ButtonCollapseViewer;

      this.isAccessibleMode = Accessibility.isAccessibleMode() ? true : false;

      this.closeButton = this.isAccessibleMode ? ViewerUtils.closeButtonAlly : ViewerUtils.closeButton;
      this.expandIcon = this.isAccessibleMode ? ViewerUtils.expandIconAlly : ViewerUtils.expandIcon;
      this.collapseIcon = this.isAccessibleMode ? ViewerUtils.collapseIconAlly : ViewerUtils.collapseIcon;
      this.popInButton = this.isAccessibleMode ? ViewerUtils.popInButtonAlly : ViewerUtils.popInButton;
      this.popOutButton = this.isAccessibleMode ? ViewerUtils.popOutButtonAlly : ViewerUtils.popOutButton;
      this.contentView = this.options['contentView'];
      if (!this._connector) {
        throw 'Models must be created with a context in order to obtain a valid connection.';
      }

      this.listenTo(this.model, 'sync', this.fetchAndLoadViewer);

      this.listenTo(this, 'panel:expand', function(){
        this.isExpanded = true;
        this.expandMode();
      });
      this.listenTo(this, 'panel:collapse', function(){
        this.isExpanded = false;
        this.expandMode();
      });
      this.isDirtyMarkup = false;
      this.listenTo(options.context, 'sync change:perspective', function() {
        if(!this.isPreviewMode && !this.isEmbeddedPreview) {
          this.isAppliedMask() && this.trigger('remove:mask');
          this.closeViewer();
        }
      }.bind(this));

      this.exportCompleteCallBackBind = this.exportCompleteCallBack.bind(this);
      $(window).off('exportComplete', this.exportCompleteCallBackBind).on('exportComplete', this.exportCompleteCallBackBind);
    },

    ui: {
      markupMigration: '#migrationInfo'
    },

    onChangeModel: function () {
      if (this.model.hasChanged('id') || this.model.hasChanged('version_number')) {
        this.render();
      }
    },

    onShow: function(){
      var me = this;
      if(this.isEmbeddedPreview) {
        DownloadCommand.prototype.fetchDownloadUrls.call(this, this.model, this.getDownloadLink(this.model)).done(function () {
          if(me.model.get("isPreviewProtected") === true) {
            me.destroy();
          } else {
            me.fetchAndLoadViewer();
          }
        }).fail(function() {
          me.destroy();
        });
      } else {
        me.fetchAndLoadViewer();
      }
    },

    fetchAndLoadViewer: function () {
      if (this.isPreviewMode ? (!this.model.fetched || this.model.fetching):!this.model.get('id')) {
        return;
      }
      var me = this,
          currentRepo = RestResources.getCurrentRepository().get('name'),
          currentUser = RestResources.getCurrentUser().get('name'),
          documentId = me.model.get('id'),
          tzoffset = FormatUtils.getTimezoneOffset(),
          el = me.el,
          elId = el.getAttribute('id'),
          href = Url.combine(me._connector.connection.url, "repositories", currentRepo, "bravaenterprise", "getClientLoadData"),
          qParams = {
            repo: currentRepo,
            log: currentUser,
            docid: documentId,
            tzoffset: tzoffset
          };

      if(this.isPreviewMode || this.contentView) {
        qParams['mode'] = 'preview';
      }
      if(this.options.isAnnotationDisable) {
        qParams['disable-annotation'] = 'true';
      }

      href = Url.appendQuery(href, Url.combineQueryString(qParams));

      if (!elId) {
        elId = 'd2-bravaenterpriseviewer' + (new Date().getTime());
        el.setAttribute('id', elId);
      }

      $.ajax(me._connector.extendAjaxOptions({
        url: href,
        type: 'GET',
        success: function (data) {
          data = JSON.parse(data);
          me._loadViewer(data);
        },
        error: function (error) {
          me.destroy();
          if (error.message){
            csui.require([
              'd2/controls/globalmessage/globalmessage'
            ], function (GlobalMessage) {
              GlobalMessage.showMessage("error", error.message, undefined, {});
            });
          }
        }
      }));
    },

    _loadViewer: function (data) {
      var me = this,
          oldClientType = me.clientType;
      me.clientType = data.clientType;
      me.checkForMigration(me.model);
      if(me.clientType !== '2D') {
        data.htmlViewerConfigUrl = data.htmlViewerConfigUrl.replace(/(\&)?mode=preview/gi, '');
      }
      if(this.isAccessibleMode) {
        data.htmlViewerConfigUrl = data.htmlViewerConfigUrl + "&accessible=true";
      }
      if(me.viewer) {
        if(me.clientType === oldClientType) {
          me.viewer.loadConfiguration({
            clientType: data.clientType,
            signedConfigUrl: data.htmlViewerConfigUrl
          }).then(function(){
            if(me.clientType === '3D') {
              setTimeout(function(){
                me._onViewerInit();
              }, 1000);
            }
          });
          return;
        } else {
          me.ignoreNextClientClosedEvent = true;
          me.closeViewer().always(me._loadViewer.bind(me, data));
        }
      }
      csui.require([
        'igc/HTML/html-clients'
      ],function loadScripts() {
        require([
          'igc/HTML/' + data.htmlClientFactory
        ], function createContent() {
          var viewer = window.brava.htmlClients.create(data.htmlClientFactory, {
            path: moduleConfig.basePath + '/igc/HTML',
            container: me.el.getAttribute('id'),
            locale: (i18n.settings.locale === 'iw') ? 'he' : i18n.settings.locale,
            clientType: data.clientType,
            logLevel: "all",
            isCrossOrigin: data.isCrossOrigin,
            corsServersEntries: data.corsServersEntries,
            height: "100%",
            width: "100%",
            nodeType: "iframe",
            signedConfigUrl: data.htmlViewerConfigUrl,
            xmlPostType: "text/xml",
            requestHeaders: me._getSharedHeaderParams(),
            onDocumentExport: 'fire-event'
          });

          viewer.then(function (api) {
            me.viewer = api;
            api.on('ClientClosed', function () {
              if(me.ignoreNextClientClosedEvent === true) {
                me.ignoreNextClientClosedEvent = false;
              } else {
                me.trigger('viewer:close');
                me.destroy();
              }
            });

            api.on('ClientClosedOnStartup', function () {
              me.destroy();
            });

            api.on('DocumentVisible', function () {
              if(me.clientType === '2D') {
                if(me.isPreviewMode === true) {
                  me._addCustomCloseButton(api);
                  if(me.isEmbeddedPreview) {
                    me._addCustomPopOutButton(api);
                  }
                  else {
                    me._addCustomExpandCollapseButton(api);
                  }
                }
                else {
                  me.options.showCollapseButton && me._addCustomPopInButton(api);
                }
              }
            });

            api.on('NewDocumentVisible', function(){
              me._onViewerInit();
            });

            api.on('MarkupDirty', function () {
              if(me.isPreviewMode) {
                !me.isAppliedMask() && me.trigger('apply:mask');
              }
              me.isDirtyMarkup = true;
            });

            api.on('MarkupSaved', function(/*args*/){
              me.isAppliedMask() && me.trigger('remove:mask');
              me.isDirtyMarkup = false;
            });

            api.on('MarkupEditClosed', function(/*args*/) {
              me.isAppliedMask() && me.trigger('remove:mask');
              me.isDirtyMarkup = false;
            });

            if(me.clientType === '3D') {
              setTimeout(function(){
                me._onViewerInit();
              }, 1000);
            }
          });

        }, function() {
          me._onViewerApiError("HTML Client Factory load error");
        });
      }, function() {
        me._onViewerApiError("HTML Client file load failed");
      });
    },

    checkForMigration: function(node) {
      var me = this;
      iViewerUtils.getMarkupMigrationStatusByObjectIds(node.connector,[node.get("id")]).done(function(statusData) {
        if(statusData && statusData.markupMigration && statusData.markupMigration.length> 0) {
          me.displayMigrationBannerInfo("BRAVA_VIEWER");
        } else {
          me.hideMigrationStatusBar();
        }
      });
    },

    hideMigrationStatusBar: function() {
      $(this.el).find(this.ui.markupMigration).addClass('binf-hidden');
      $(this.el).find(this.ui.markupMigration).removeClass('with-migration-status');
    },

    displayMigrationBannerInfo: function(viewerType) {
      var region = new Marionette.Region({el: this.ui.markupMigration});
      var view = new markupMigrationView({
        viewerType: viewerType,
      });
      this.showMigrationStatusBar();
      region.show(view);
    },

    showMigrationStatusBar() {
      $(this.el).find(this.ui.markupMigration).removeClass('binf-hidden');
      $(this.el).find(this.ui.markupMigration).addClass('with-migration-status');
    },

    _getSharedHeaderParams: function () {
      var headers = {};
      this.model.connector.authenticator.setAuthenticationHeaders(headers);
      headers["Accept-Language"] = (i18n.settings.locale === 'iw') ? 'he' : i18n.settings.locale;
      return headers;
    },

    _addCustomCloseButton: function(bravaApi) {
      var me = this;
      this._addCustomButton(bravaApi, {
        varName: 'customCloseButton',
        tooltip: lang.ButtonCloseViewer,
        icon: me.closeButton,
        placement: {
          toolbarRegion: 'End',
          buttonPosition: 'Last'
        },
        pinWidget: true,
        cssStyle: me.isAccessibleMode ? '' : 'background-color: transparent;',
        handler: function customClick(e) {
          e = e ? $.Event(event) : e;
          me.checkDirtyMarkupAndCloseOrPopOut(e, true);
        }
      });
    },

    _addCustomPopOutButton: function(bravaApi) {
      var me = this;
      this._addCustomButton(bravaApi, {
        varName: 'customPopOutButton',
        tooltip: lang.ButtonExpandViewer,
        icon: me.popOutButton,
        placement: {
          toolbarRegion: 'Start',
          buttonPosition: 'First'
        },
        pinWidget: true,
        cssStyle: me.isAccessibleMode ? '' : 'background-color: transparent;',
        handler: function customClick(e) {
          e = e ? $.Event(event) : e;
          me.checkDirtyMarkupAndCloseOrPopOut(e, false); //popout
        }
      });
    },

    saveMarkupConfirmDialog: function() {
      var deferred = $.Deferred();
      var buttonOptions = {
        labelYes: lang.SaveMarkupDialogButtonYes,
        labelNo: lang.SaveMarkupDialogButtonNo,
        showNo: true,
        showCancel: true
      };

      ModalAlert.confirmQuestion(function (result) {
        if (result === true) {
          deferred.resolve();
        }
        if (result === false) {
          deferred.reject();
        }
      }, lang.SaveMarkupDialogBody, lang.SaveMarkupDialogHeader, {
        buttons: buttonOptions,
        modalClass: 'd2-be-sm-dialog'
      });

      return deferred.promise();
    },

    _addCustomPopInButton: function(bravaApi) {
      var me = this;
      this._addCustomButton(bravaApi, {
        varName: 'customPopInButton',
        tooltip: lang.ButtonCollapseViewer,
        icon: me.popInButton,
        placement: {
          toolbarRegion: 'Start',
          buttonPosition: 'First'
        },
        pinWidget: true,
        cssStyle: me.isAccessibleMode ? '' : 'background-color: transparent;',
        handler: function customClick(/*e*/) {
          me.checkDirtyMarkupAndCloseOrPopOut(undefined, true); //close viewer
        }
      });
    },

    checkDirtyMarkupAndCloseOrPopOut: function(e, close) {
      var me = this;
      if(this.isDirtyMarkup) {
        this.saveMarkupConfirmDialog().done(function() {
          me.viewer.saveMarkupFile({
          }).then(function(result) {
            if(result) {
              close ? me.doClose(e) : me.doPopOut(e);
            }
          });
        }).fail(function() {
          me.viewer.closeMarkupFile({forceClose: true}).then(function() {
            close ? me.doClose(e) : me.doPopOut(e);
          });
        });
      }
      else {
        close ? me.doClose(e) : me.doPopOut(e);
      }
    },

    doClose: function(e) {
      this.trigger('viewer:close', e);
      if(this.isExpanded) {
        this.trigger('overlay:panel:collapse');
        this.isExpanded = false;
        this.expandMode();
      }
      if(!e || !e.isDefaultPrevented()) {
        this.closeViewer();
      }
    },

    doPopOut: function(e) {
      this.trigger('viewer:expand', e);
    },

    _addCustomExpandCollapseButton: function(bravaApi) {
      var me = this;
      this._addCustomButton(bravaApi, {
        varName: 'customExpandCollapseButton',
        tooltip: me.expandButtonTooltip,
        icon: me.expandIcon,
        placement: {
          toolbarRegion: 'Start',
          buttonPosition: 'First'
        },
        pinWidget: true,
        cssStyle: 'margin-left: -15px;' + (!me.isAccessibleMode ? 'background-color: #3F4950;' : ''),
        handler: function customClick(e) {
          e = e ? $.Event(event) : e;
          if (!me.isExpanded) {
            me.trigger('overlay:panel:expand', e);
            me.isExpanded = true;
            me.expandMode();
          } else {
            me.trigger('overlay:panel:collapse');
            me.isExpanded = false;
            me.expandMode();
          }
        }
      });
    },

    _addCustomButton: function (bravaApi, options) {
      /*var me = this,
        setBtnBg = function (e, icon) {
          var elId = 'customBravaWidgetId_' + e.targetId,
            btnEl = $('#' + me.el.getAttribute('id') + ' iframe').contents().find('.dijitButton[widgetId=' + elId + ']');
          btnEl.css({
            backgroundImage: 'url("' + icon + '")'
          });
        };*/
      if (bravaApi[options.varName] === undefined) {
        var optionsCssStyle = options.cssStyle ? options.cssStyle : '';

        bravaApi[options.varName] = bravaApi.addCustomButton({
          type: 'Button',
          showLabel: false,
          toolTip: options.tooltip,
          icon: options.icon,
          cssStyleAdjustments: optionsCssStyle + 'background-position:center; background-size:24px 24px ' + (options.applyRTLStyleForIcon === true && i18n.settings.rtl ? '; transform: scaleX(-1)' : ''),
          container: {
            name: 'TaskBar',
            placement: options.placement ? options.placement : {
              toolbarRegion: 'Start',
              index: options.position
            }
          },
          pinWidget: (options.pinWidget === true),
          eventHandlers: {
            click: options.handler
          }
        });
      }
    },

    _onViewerApiError: function(error) {
      this.trigger('viewer:error', error);
    },

    expandMode: function() {
      var me = this, img;
      this.viewer['customExpandCollapseButton'].then(function(buttonData) {
        var btnEl = $('#' + me.el.getAttribute('id') + ' iframe').contents().find('.dijitButton[widgetId=' + buttonData.id + ']');
        var btnInnerEl = $('#' + me.el.getAttribute('id') + ' iframe').contents().find('#'+buttonData.id);
        if(me.isExpanded) {
          if(me.isAccessibleMode) {
            img = $(btnInnerEl).find("img");
            $(img).prop("src", me.collapseIcon);
          } else {
            btnEl.css({
              backgroundImage: 'url("' + me.collapseIcon + '")'
            });
          }
          btnInnerEl.prop('title', me.collapseButtonTooltip);
        }
        else {
          if(me.isAccessibleMode) {
            img = $(btnInnerEl).find("img");
            $(img).prop("src", me.expandIcon);
          } else {
            btnEl.css({
              backgroundImage: 'url("' + me.expandIcon + '")'
            });
          }
          btnInnerEl.prop('title', me.expandButtonTooltip);
        }
      });
    },

    exportCompleteCallBack: function(e) {
      this.showPublishDialog(e);
    },

    showPublishDialog: function(e) {
      var dialog = new PublishDialog({
        publishUrl: e.detail.url,
        type: e.detail.type,
        node: this.model,
        context: this.options.context,
        addExtraOptions: [PublishFieldsConstant.publishOptions.CURRENT_LOCATION, PublishFieldsConstant.publishOptions.VERSION, PublishFieldsConstant.publishOptions.RENDITION],
        defaultFileName: this.model.get('name')
      });
      dialog.show();
    },

    onDestroy: function() {
      $(window).off('exportComplete', this.exportCompleteCallBackBind);
    },

    _onViewerInit: function() {
      this.trigger('viewer:init');
    },

    reloadViewer: function() {
      this.fetchAndLoadViewer();
    },

    onBeforeDestroy: function () {
      this.viewer && this.viewer.closeViewer({allowCancel: false});
    },

    getDownloadLink: function (node) {
      var url = RestLinkrels.getLink(node.get('links'), RestLinkrels.PREVIEW_URLS);
      var qParams = {
        format: node.get('aContentType') || node.get('a_content_type')
      }
      url = Url.appendQuery(url, Url.combineQueryString(qParams));
      return url;
    },

    closeViewer: function() {
      var dfd = $.Deferred();
      if(this.viewer) {
        this.viewer.closeViewer({allowCancel: false}).then(function(){
          dfd.resolve();
        }, function(){
          this._onViewerApiError();
          dfd.reject();
        }.bind(this));
      } else {
        dfd.reject();
      }

      return dfd.promise();
    }
  });

  return BravaEnterpriseView;
});

csui.define('css!d2/commands/open.plugins/impl/brava.iviewer',[],function(){});

csui.define('d2/commands/open.plugins/impl/brava.iviewer.view',[
  'nuc/lib/underscore',
  'nuc/lib/jquery',
  'nuc/utils/url',
  'nuc/lib/backbone',
  'nuc/lib/marionette',
  'csui/utils/contexts/factories/node',
  'd2/utils/rest.linkrels',
  'dctmw/utils/rest.resources',
  'i18n!d2/commands/open.plugins/nls/localized.strings',
  'dctmw/dialogs/authentication/oauth.login.dialog',
  'nuc/utils/log',
  'csui/controls/progressblocker/blocker',
  'd2/utils/server.query.utils',
  'd2/utils/widget.constants',
  'd2/controls/globalmessage/globalmessage',
  'd2/controls/behaviors/viewer.masking.behavior',
  'd2/commands/open.plugins/impl/iviewer/utils',
  'd2/commands/open.plugins/impl/viewer.utils',
  'csui/dialogs/modal.alert/modal.alert',
  'd2/commands/open.plugins/impl/markup.migration/view',
  'dctmw/utils/client.location',
  'd2/commands/download',
  'css!d2/commands/open.plugins/impl/brava.iviewer'
], function (_, $, Url, Backbone, Marionette, NodeModelFactory, RestLinkrels, RestResources,
             lang, OAuthLoginDialog, log, BlockingView, serverQueryUtils, widgetConstants, GlobalMessage,
             ViewerMaskingBehavior, iViewerUtils, viewerUtils, ModalAlert, markupMigrationView, clientLocation,
             DownloadCommand) {

  'use strict';

  var isIVAnnotateDisabled,
      layout,
      userLanguage,
      currentUser = RestResources.getCurrentUser();

  if (currentUser && !_.isEmpty(currentUser)) {
    userLanguage = currentUser.get('preferences')['default_language'];
  }

  var store = [{accessToken: null, accessTokenExpiry: null}];
  var viewerClassName = 'd2-bravaintelligentviewer';
  var appleMatches = navigator.userAgent.match(/(iPad)/i);
  if (appleMatches) {
    viewerClassName = 'd2-brava-iviewer-ipad';
  }

  if (userLanguage && !_.isEmpty(userLanguage)) {
    window.___BRAVA_LOCALE___ = userLanguage;
  }

  return Marionette.ItemView.extend({
    className: viewerClassName,
    template: _.template('<div id="migrationInfo" class="migration-info binf-hidden"></div><div id="bravaViewRoot" class="d2-iv-viewer-div"></div>'),

    behaviors: {
      MaskingBehavior: {
        behaviorClass: ViewerMaskingBehavior
      }
    },

    constructor: function BravaIntelligentViewer(options) {
      this.ivWidgetConfiguration = null;
      this.intelligentViewerConfig = null;
      this.ivWidgetName = null;

      if (options == null) {
        log.error("OpenText Intelligent Viewing options is missing");
        return;
      }
      if (!options.model) {
        options.model = options.context.getModel(NodeModelFactory, {
          attributes: {
            id: options.data.id,
            version_number: options.data.version_number
          }
        });
      }
      Marionette.ItemView.prototype.constructor.call(this, options);
      this.isPreviewMode = options.isPreviewMode;
      this.isContentView = this.model['popOutWindow'] ? true : false;
      this.isEmbeddedPreview = options.isEmbeddedPreview ? options.isEmbeddedPreview : false;

      if (this.options.blockingParentView) {
        BlockingView.delegate(this, this.options.blockingParentView);
      } else {
        BlockingView.imbue(this);
      }
      this.api = null;
      this.isExpanded = false;
      this.documentIdAdded = null;

      this.listenTo(this.model, 'change', this.onChangeModel);

      this.listenTo(this, 'panel:expand', function () {
        this.isExpanded = true;
        this.showCollapseViewerButton();
      }.bind(this));
      this.listenTo(this, 'panel:collapse', function () {
        this.isExpanded = false;
        this.showExpandViewerButton();
      }.bind(this));

      this.viewerId = _.uniqueId('viewer_');
      this.migrationStatusId = _.uniqueId('migration_');
      this.isRelatePermission = false;

      this.initIntelligentViewerConfig();
      this.listenTo(options.context, 'sync change:perspective', function() {
        //this.viewerContentHide(); //for unload document
        this.clearViewer();
        this._doClose();
      }.bind(this));
    },

    ui: {
      markupMigration: '#migrationInfo'
    },

    initIntelligentViewerConfig: function () {
      this.bearerToken = null;
      this.bravaIVConfiguration = null;
      this.currentPageConfig = null;

      const params = clientLocation.getHashParams();

      if(params && !_.isEmpty(params['viewer-name']) && this.model["viewerWidgetName"]) {
        this.ivWidgetName = params['viewer-name'];
      }
      if (currentUser && !_.isEmpty(currentUser) && _.isEmpty(this.ivWidgetName)) {
        var userDefaultWidgets = currentUser.get('defaultWidgets');
        if (userDefaultWidgets && !_.isEmpty(userDefaultWidgets) && !_.isEmpty(userDefaultWidgets[widgetConstants.DEFAULT.BRAVAIV])) {
          this.ivWidgetName = userDefaultWidgets[widgetConstants.DEFAULT.BRAVAIV];
        }
      }
      if (!_.isEmpty(this.ivWidgetName)) {
        this.ivWidgetConfiguration = serverQueryUtils.getWidgetConfig(widgetConstants.D2.BRAVAIV, this.ivWidgetName);
      }
      if (this.ivWidgetConfiguration && !_.isEmpty(this.ivWidgetConfiguration)) {
        this.intelligentViewerConfig = JSON.parse(this.ivWidgetConfiguration.widgetParams["brava_iv_configuration"]);
        isIVAnnotateDisabled = this.ivWidgetConfiguration.widgetParams["is_brava_iv_disable_annotate"];
      }
      if (isIVAnnotateDisabled) {
        var removeAnnotationFeature = this.intelligentViewerConfig.leftTabContainer.tabs;
        _.each(removeAnnotationFeature, function (item) {
          if (item !== undefined && item.component === 'MarkupPane') {
            removeAnnotationFeature.splice(removeAnnotationFeature.indexOf(item), 1);
          }
        });
      }
      if (this.intelligentViewerConfig && !_.isEmpty(this.intelligentViewerConfig)) {
        layout = _.defaults(
            {
              mainContainer: [
                {component: 'TabContainer', layoutKey: 'leftTabContainer'},
                {component: 'PageContainer'}
              ]
            }, this.intelligentViewerConfig);

        if(layout.compareToolbar) {
          delete layout.compareToolbar;
        }
      }
      this.bravaReadyEventCallBackBind = this.bravaReadyEventCallBack.bind(this);
      $(window).off('bravaReady', this.bravaReadyEventCallBackBind).on('bravaReady', this.bravaReadyEventCallBackBind);
    },

    bravaReadyEventCallBack: function (e) {
      if(this.currentPageConfig) {
        return;
      }
      var me = this;
      this.currentPageConfig = e.detail;
      $("body").addClass("ot-iviewer-overflow");
      this.setViewerConfig();

      if(this.isPreviewMode) {
        if (this.isEmbeddedPreview) {
          $(this.el).addClass('d2-embedded-preview');
          this.api.hideToolbarButtons(['popInViewerButtonButton', 'expandViewerButtonButton', 'collapseViewerButtonButton']);
        }
        else {
          this.api.hideToolbarButtons(['popInViewerButtonButton', 'popOutViewerButtonButton', 'collapseViewerButtonButton']);
          this.isExpanded && this.showCollapseViewerButton();
        }
      }
      else {
        this.api.hideToolbarButtons(['popInViewerButtonButton', 'popOutViewerButtonButton', 'expandViewerButtonButton', 'collapseViewerButtonButton']);
        this.options.showCollapseButton && this.api.unhideToolbarButtons(['popInViewerButtonButton']);
      }
      if(this.isContentView) {
        this.api.hideToolbarButtons(['CloseButton']);
      }

      // called from onShow
      this.getPublicationDeferred.done(function(response) {
        me.addPublication(response);
      })
          .fail(function(errorResponse) {
            me._pageRendered();
            var error = errorResponse.responseJSON;
            ModalAlert.showError(error.message);
            me.destroy();
          })
          .always(function() {
            me.unblockActions();
          });
    },

    _closeEvent: function (e) {
      this.migrationStatusTimer && clearInterval(this.migrationStatusTimer);
      this.checkDirtyMarkupAndCloseOrPopOut(e, true);
    },

    _doClose: function(e) {
      this.isAppliedMask() && this.trigger('remove:mask');
      this.trigger('viewer:close', e);
      if(this.isEmbeddedPreview){
        return;
      }
      if(this.needMarkupCountUpdate) {
        iViewerUtils.getMarkupCounts(this.model.connector, [this.model.get("id")]).done(function(data) {
          var objData = data.markupCount[this.model.get("id")];
          this.model.trigger("update:viewer:markup:count", objData.markup_count);
          this.needMarkupCountUpdate = false;
        }.bind(this));
      }
      if(this.isPreviewMode) {
        if(this.isExpanded) {
          this.trigger('overlay:panel:collapse');
          this.isExpanded = false;
          this.showExpandViewerButton();
        }
        this.clearViewer();
        //this.viewerContentHide(); // for unload
        return;
      }
      this._setPredicates(false);
      this.destroy();
    },

    onRender: function() {
      $(this.el).find('.d2-iv-viewer-div').attr('id', this.viewerId);
      $(this.el).find('.migration-info').attr('id', this.migrationStatusId);
      this.pageUnloadBind = this._pageUnloadEvent.bind(this);
      this.container = $(this.el).find("#" + this.viewerId);
      this.container.on('markupsDirty', this._markupsDirtyEvent.bind(this));

      this.container.on('close', this._closeEvent.bind(this));
      this.container.on('pageRender', this._pageRendered.bind(this));
      this.container.on('markupFeaturesAvailable', this._markupFeaturesAvailableEvent.bind(this));
      this.container.on('exportSuccess-download', this._exportSuccessDownloadEvent.bind(this));
      this.container.on('expandViewerButtonClick', this._expandViewerButtonClickEvent.bind(this));
      this.container.on('popOutViewerButtonClick', this._popOutViewerButtonClickEvent.bind(this));
      this.container.on('popInViewerButtonClick', this._popInViewerButtonClickEvent.bind(this));
      this.container.on('collapseViewerButtonClick', this._collapseViewerButtonClickEvent.bind(this));
      this.container.on('svgPageLoadFailure', this._svgPageLoadFailureEvent.bind(this));
      $(window).on('beforeunload', this.pageUnloadBind);
    },

    _pageUnloadEvent: function(/*e*/) {
      if(this.isDirtyMarkup) {
        return true;
      }
    },

    onBeforeDestroy: function () {
      $(this.el).html('');
      $(window).off('bravaReady', this.bravaReadyEventCallBackBind);
      $(window).off('beforeunload', this.pageUnloadBind);
      $("body").removeClass("ot-iviewer-overflow");
    },

    _pageRendered: function () {
      this.unblockActions();
      this.trigger('viewer:init');
      this._setPredicates(!this.isAnnotateDisabled());
    },

    _setPredicates : function(isEnabled) {
      var me = this;

      this.api.commentableMarkupPredicate = function (/*markup*/) {
        return isEnabled;
      };
      this.api.editableMarkupPredicate = function(markup) {
        return me._canPredicate(markup, isEnabled);
      };

      this.api.deletableMarkupPredicate = function(markup) {
        return me._canPredicate(markup, isEnabled);
      };

      this.api.deletableStampPredicate = function (stamp) {
        return me._canPredicate(stamp, isEnabled);
      };

      this.api.editableStampPredicate = function (stamp) {
        return me._canPredicate(stamp, isEnabled);
      };

      this.api.addableStampPredicate  = function (/*stamp*/) {
        return isEnabled;
      };

      this.api.visibleCommandPredicate = function(key) {
        if (key === 'addToNewStamp') {
          return isEnabled;
        }
      };
    },

    _canPredicate : function (feature, isEnabled){
      if(!isEnabled) {
        return false;
      }
      return feature.author === RestResources.getCurrentUser().get('name');
    },

    _markupFeaturesAvailableEvent: function () {
      if(this.intelligentViewerConfig && this.intelligentViewerConfig.imageRaster) {
        this.api.addRasters(this.intelligentViewerConfig.imageRaster);
      }
    },

    _svgPageLoadFailureEvent: function (/*e*/) {
      this.unblockActions();
      this.reloadViewer();
    },

    _exportSuccessDownloadEvent: function (e) {
      if (e) {
        var loadSourcesProp, loadSources, sourceDocName, artifact, exportType, urlTemplate, content,
            url, downloadFileName;
        loadSourcesProp = Object.keys(e.detail._embedded['otc:get_configs_id'].features).filter(
            function (property) {
              return property.startsWith('opentext.publishing.sources@LoadSources@')
            });
        loadSources = loadSourcesProp ? Object.values(e.detail._embedded['otc:get_configs_id'].features[loadSourcesProp].documents) : undefined;
        sourceDocName = loadSources ? loadSources[0].filenameHint : undefined;

        artifact = e.detail._embedded['pa:get_publication_artifacts'][0]._embedded['ac:get_artifact_content'];

        if (artifact) {
          exportType = artifact.acceptHint ? artifact.acceptHint === 'application/pdf' ? 'pdf' : 'tiff' : '';
          urlTemplate = artifact.urlTemplate;
          content = artifact.contentLinks[0]
        }
        if (urlTemplate) {
          url = urlTemplate
              .replace('{id}', content.id)
              .replace('{name}', content.name)
              .replace('{type}', content.type)
              .replace('{file}', content.file);
        }
        if (sourceDocName) {
          downloadFileName = sourceDocName.replace(loadSources[0].formatHint, exportType);
        }
        if (url) {
          $.ajax({
                url: url,
                type: 'GET',
                dataType: 'binary',
                headers: {
                  authorization: this.bearerToken
                },
                success: function (response) {
                  var blob = new Blob([response], {type: response.type}),
                      url = window.URL.createObjectURL(blob),
                      link = document.createElement("a");
                  link.download = downloadFileName;
                  link.href = url;
                  link.click();
                  window.URL.revokeObjectURL(url);
                },
                error: function (error) {
                  console.log('Failed to download the published document', error);
                }
              }
          );
        }
      }
    },

    _expandViewerButtonClickEvent: function (e) {
      this.trigger('overlay:panel:expand', e);
      this.showCollapseViewerButton();
      //Todo: global variable is not required on custom close
      this.isExpanded = true;
    },

    _collapseViewerButtonClickEvent: function (e) {
      this.trigger('overlay:panel:collapse', e);
      this.showExpandViewerButton();
      //Todo: global variable is not required on custom close
      this.isExpanded = false;
    },

    _popOutViewerButtonClickEvent: function(e) {
      this.checkDirtyMarkupAndCloseOrPopOut(e, false);
    },

    _popInViewerButtonClickEvent: function(e) {
      this.checkDirtyMarkupAndCloseOrPopOut(e, true);
    },

    checkDirtyMarkupAndCloseOrPopOut: function(e, close) {
      var me = this;
      if(this.isDirtyMarkup) {
        this.showSaveMarkupDialog().done(function(/*data*/) {
          me.api.save();
          $("body").find('#ot-iv-tool-properties').hide();
          close ? me._doClose(e) : me._doPopOut(e);
        }).fail(function() {
          me.api.restoreToLastSave();
          me.isDirtyMarkup = false;
          me.isAppliedMask() && me.trigger('remove:mask');
          $("body").find('#ot-iv-tool-properties').hide();
          close ? me._doClose(e) : me._doPopOut(e);
        });
      }
      else {
        $("body").find('#ot-iv-tool-properties').hide();
        close ? me._doClose(e) : me._doPopOut(e);
      }
    },

    _doPopOut: function(e) {
      this.trigger('viewer:expand', e);
    },

    setPublicationToViewer: function (loginToken) {
      var me = this, deferred = $.Deferred();
      this._getPublication(loginToken).done(function (response) {
        me.addPublication(response);
        deferred.resolve();
      }).fail(function (errorResponse) {
        me.destroy();
        var error = errorResponse.responseJSON;
        ModalAlert.showError(error.message);
        deferred.reject();
      });
      return deferred.promise();
    },

   addPublication: function(response) {
         var publication;
          if(response && response.publications && response.publications.length>1) {
          var publicationIds = [];
          let failedPublicationDocMap = new Map();
          var documentIds = [];
          var documentId;
          for (var i = 0; i < response.publications.length; i++) {
              publication = JSON.parse(response.publications[i]);
              documentId = this.options.previewNodes.models[i].attributes.i_chronicle_id;
              if (publication.status === 'Failed' || publication.publicationErrorForFile) {
                failedPublicationDocMap.set(documentId, publication);
              }
              var publicationId = publication.id;
              documentIds.push(documentId);
              this.api.addPublication(publication, true, documentId);
              if(publicationId != undefined) {
                publicationIds.push(publicationId);
              }
          }

          this.api.viewBinder(publicationIds);
          setTimeout(function() {
              this.checkForMigration(this.model.connector, documentIds);
           }.bind(this), 1000)

             if(failedPublicationDocMap.size == 1) {
             GlobalMessage.showMessage("error", _.str.sformat(lang.IVSingleDocumentViewBinderError, (publication.publicationErrorForFile ? publication.publicationErrorForFile :  publication.featureSettings[0].value[0].filenameHint)));
             } else if(failedPublicationDocMap.size>1) {
                viewerUtils.handleViewBinderError(failedPublicationDocMap, this);
             }
          } else {
               publication = JSON.parse(response);
               if (publication.status === 'Failed' || publication.publicationErrorForFile) {
                   this._pageRendered();
                   GlobalMessage.showMessage("error", lang.IVDocumentLoadError);
               } else {
                       documentId = this.model.get('id');
                       this.documentIdAdded = documentId;
                       this.api.addPublication(publication, true, documentId);
                       setTimeout(function() {
                           this.checkForMigration(this.model.connector,[documentId]);
                       }.bind(this), 1000)
                       //this.viewerContentShow();
               }
        }
       },

    setViewerConfig: function () {
      this.api = window[this.currentPageConfig];
      this.api.setAutoRender(false);
      this.setLayout();
      this.api.setHttpHeaders({'Authorization': this.bearerToken});
      this.api.setSearchHost(this.bravaIVConfiguration.brava_highlight_service_url);
      this.api.setMarkupHost(this.bravaIVConfiguration.brava_markup_service_url);
      this.api.setUserName(RestResources.getCurrentUser().get('name'));
      //window.api.addPublication(publication, true, documentId);
      this.api.enableMarkup(true);
      this.api.setActiveTab("tab.thumbnails");
      this.api.render(this.viewerId);
    },

    setLayout: function(isAnnotationDisable) {
      var layoutClone = JSON.parse(JSON.stringify(layout));

      if(isAnnotationDisable || this.isAnnotateDisabled()) {
        var removeAnnotationFeature = layoutClone.leftTabContainer.tabs;
        removeAnnotationFeature = removeAnnotationFeature.filter(function (value/*, index, arr*/) {
          if (_.contains(['MarkupPane', 'StampRasterPane', 'TakeoffPane'], value.component)) {
            return false;
          } else {
            return true;
          }
        });
        layoutClone.leftTabContainer.tabs = removeAnnotationFeature;
      }
      iViewerUtils.setHelpUrl(layoutClone).done(function() {
        this.api.setLayout(layoutClone);
      }.bind(this));

    },

    isAnnotateDisabled: function() {
      var disabled = false;
      if(this.options && this.options.isAnnotationDisable) {
        disabled = true;
      } else if(isIVAnnotateDisabled) {
        disabled = true;
      } else if (!this.isRelatePermission) {
        disabled = true;
      }
      return disabled;
    },

    onChangeModel: function () {
      if (this.model.hasChanged('id') || this.model.hasChanged('version_number')) {
        this.render();
      }
    },

    onShow: function() {
      var me = this;
      this.blockActions();
      if(this.isEmbeddedPreview) {
        DownloadCommand.prototype.fetchDownloadUrls.call(this, this.model, this.getDownloadLink(this.model)).done(function () {
          if(me.model.get("isPreviewProtected") === true) {
            me.destroy();
          } else {
            me._onShow();
          }
        }).fail(function() {
          me.destroy();
        });
      } else {
        this._onShow();
      }
    },

    _onShow: function () {
      var me = this;
      iViewerUtils.getBravaIViewerConfiguration(this.model.connector).done(function(bravaIViewerConfigutation) {
        me.bravaIVConfiguration = bravaIViewerConfigutation;
        iViewerUtils.getAccessToken(me.model.connector).done(function(token) {
          me.bearerToken = 'Bearer ' + token;
          me.getPublicationDeferred = me._getPublication(token);
          viewerUtils.isRelatePermission(me.model.connector, [me.model.get('id')]).done(function(permission) {
            me.isRelatePermission = permission;
            me._loadBravaViewerScripts();
          });
        }).fail(function () {
          GlobalMessage.showMessage("error", lang.IVDocumentLoadError);
          me.destroy();
        });
      });
    },

    reloadViewer: function () {
      var me = this;
      this.clearViewer();
      this.migrationStatusTimer && clearInterval(this.migrationStatusTimer);
      this.hideMigrationStatusBar();
      this.blockActions();
      iViewerUtils.getAccessToken(this.model.connector).done(function(token) {
        me.bearerToken = 'Bearer ' + token;
        me.api.setHttpHeaders({'Authorization': me.bearerToken});
        if (me.documentIdAdded !== me.model.get('id')) {
          me.api.setSidebarOpen(false);
          viewerUtils.isRelatePermission(me.model.connector, [me.model.get('id')]).done(function(permission) {
            me.isRelatePermission = permission;
            me.setPublicationToViewer(token).always(function() {
              me.unblockActions();
              me.setLayout();
            });
          });
        } else {
          this._pageRendered();
          //this.viewerContentShow();
        }
      }).fail(function () {
        GlobalMessage.showMessage("error", lang.IVDocumentLoadError);
        me.destroy();
      });
    },

    _validateLogin: function (connector) {
      var me = this;
      var authUrl = this.bravaIVConfiguration.otds_service_url + "/otdsws/login";
      if (me._getAccessToken()) {
        me.bearerToken = 'Bearer ' + me._getAccessToken();
        return $.Deferred().resolve().promise();
      } else {
        var dialog = new OAuthLoginDialog({
          connector: connector,
          url: authUrl,
          clientId: this.bravaIVConfiguration.otds_client_id,
          strings: {
            title: lang.OAuthLoginDialogTitle,
            authError: lang.OAuthLoginDialogAuthError
          }
        });
        return dialog.login().then(function (accessToken, expiresIn) {
          log.debug(accessToken);
          me._setAccessToken(accessToken, expiresIn);
          me.bearerToken = 'Bearer ' + me._getAccessToken();
          return $.Deferred().resolve().promise();
        }).catch(function () {
          return $.Deferred().reject('LOGIN ERROR').promise();
        });
      }
    },

    _getAccessToken: function () {
      var token = store.accessToken,
          expiry = store.accessTokenExpiry;
      if (token && expiry && (new Date().getTime()) < (expiry - 60000)) { // 1 min buffer
        return token;
      } else {
        delete store.accessToken;
        delete store.accessTokenExpiry;
      }
    },

    _setAccessToken: function (accessToken, expiresIn) {
      if (!expiresIn) {
        expiresIn = 900; // Default to 15min
      }
      store.accessToken = accessToken;
      store.accessTokenExpiry = (new Date().getTime()) + (expiresIn * 1000);
    },

    _getBravaViewerLoaderScript: function () {
      var viewerUrl = this.bravaIVConfiguration.brava_viewer_service_url + "/viewer/api/v1/viewers/brava-view-1.x/loader";
      return $.ajax({
        url: viewerUrl,
        type: 'GET',
        headers: {
          'Authorization': this.bearerToken
        }
      });
    },

    _loadBravaViewerScripts: function () {
      var me = this;
      var ivScript = document.getElementById('IV-Script');
      if (ivScript !== undefined && ivScript !== null) {
        var scriptText = ivScript.innerText;
        ivScript.remove();
        me._appendIVScript(scriptText);
        return;
      }
      this._getBravaViewerLoaderScript().done(function (response) {
        me._appendIVScript(response);
      }).fail(function (e) {
        me.unblockActions();
        GlobalMessage.showMessage("error", lang.IVDocumentLoadError);
        me.destroy();
        console.error('User seems to be forbidden' + e);
      });
    },

    _getPublication: function (loginToken) {
      var publicationAPIUrl;
       if (this.ivWidgetName && !_.isEmpty(this.ivWidgetName)) {
            var queryParam = 'widget_name=' + this.ivWidgetName;
            if(this.options.previewNodes && this.options.previewNodes.models && this.options.previewNodes.models.length >1) {
              var currRepoLinks = RestResources.getCurrentRepository().get('links');
              var publicationUrl = Url.combine(RestLinkrels.getLink(currRepoLinks, RestLinkrels.SELF), 'objects/iviewer-publication');
              queryParam += '&';
              this.options.previewNodes.models.forEach((model, index) => {
                  queryParam += 'object-ids=' + model.attributes.i_chronicle_id;
                  if (index < this.options.previewNodes.models.length - 1) {
                      queryParam += '&';
                  }
              });
              publicationAPIUrl = Url.appendQuery(publicationUrl, Url.combineQueryString(queryParam, 'publicationForViewBinder= true'));
            } else {
              publicationAPIUrl = RestLinkrels.getLink(this.model.get("links"), RestLinkrels.D2_BRAVAIVIEWER_PUBLICATION);
              publicationAPIUrl = Url.appendQuery(publicationAPIUrl, Url.combineQueryString(queryParam));
              }
            }
      return $.ajax(this.model.connector.extendAjaxOptions({
        url: publicationAPIUrl,
        type: 'GET',
        contentType: "application/json",
        headers: {
          'IV-LOGIN-TOKEN': loginToken
        },
      }));
    },

    loadBravaIViewerConfiguration: function () {
      return iViewerUtils.getBravaIViewerConfiguration(this.model.connector).done((config) => {
        this.bravaIVConfiguration = config;
      });
    },

    showExpandViewerButton: function () {
      this.api.unhideToolbarButtons(['expandViewerButtonButton']);
      this.api.hideToolbarButtons(['collapseViewerButtonButton']);
    },

    showCollapseViewerButton: function () {
      this.api.unhideToolbarButtons(['collapseViewerButtonButton']);
      this.api.hideToolbarButtons(['expandViewerButtonButton']);
    },

    _appendIVScript: function (scriptText/*, deferred*/) {
      var viewerScripts = document.createElement("script");
      viewerScripts.type = "text/javascript";
      viewerScripts.innerHTML = scriptText;
      viewerScripts.id = 'IV-Script';
      /* need to revisit  viewerScripts.onerror as this is not getting called in actual scanario */
      viewerScripts.onerror = function () {
        log.error('Error loading Viewer scripts');
      };
      $("head").append(viewerScripts);
    },

    _markupsDirtyEvent: function(markup) {
      if(markup.detail > 0) {
        this.isDirtyMarkup = true;
        this.needMarkupCountUpdate = true;
        if(this.isPreviewMode) {
          !this.isAppliedMask() && this.trigger('apply:mask');
        }
      }
      else {
        this.isDirtyMarkup = false;
        this.isAppliedMask() && this.trigger('remove:mask');
      }
    },

    showSaveMarkupDialog: function() {
      var deferred = $.Deferred();
      var buttonOptions = {
        labelYes: lang.SaveMarkupDialogButtonYes,
        labelNo: lang.SaveMarkupDialogButtonNo,
        showNo: true,
        showCancel: true
      };

      ModalAlert.confirmQuestion(function (result) {
        if (result === true) {
          deferred.resolve();
        }
        if (result === false) {
          deferred.reject();
        }
      }, lang.SaveMarkupDialogBody, lang.SaveMarkupDialogHeader, {
        buttons: buttonOptions,
        modalClass: 'd2-iv-sm-dialog'
      });

      return deferred.promise();
    },

    viewerContentShow: function() {
      $(this.el).removeClass('viewer-content-hidden');
    },

    viewerContentHide: function() {
      $(this.el).addClass('viewer-content-hidden');
    },

    clearViewer: function() {
      if (this.api.clearViewer) {
        this.documentIdAdded = null;
        this.api.clearViewer();
      }
    },

    checkForMigration: function(connector, documentIds) {
      var me = this;
      if(this.isMigrationEnabled()) {
        iViewerUtils.getMarkupMigrationStatusByObjectIds(connector, documentIds).done(function(statusData) {
          if(me.isMigrationStatusInProgress(statusData) || me.isMigrationStatusTitleUpdateFailed(statusData)) {
            me.setLayout(true);
            me.needMarkupCountUpdate = true;
            me.displayMigrationStatus(iViewerUtils.migrationStatusInprogress, connector, documentIds);
          }
        });

      }
    },

    hideMigrationStatusBar: function() {
      $(this.el).find("#" + this.migrationStatusId).addClass('binf-hidden');
      $(this.el).find("#" + this.viewerId).removeClass('with-migration-status');
    },

    showMigrationStatusBar() {
      $(this.el).find("#" + this.migrationStatusId).removeClass('binf-hidden');
      $(this.el).find("#" + this.viewerId).addClass('with-migration-status');
    },

    displayMigrationStatus: function(status, connector, documentIds) {
      var me = this, region = new Marionette.Region({el: this.ui.markupMigration});
      var view = new markupMigrationView({
        status: status,
        reloadClick: function () {
          me.reloadViewer();
        }
      });
      this.showMigrationStatusBar();
      region.show(view);
      if(status == iViewerUtils.migrationStatusInprogress) {
        this.startPoolingMigrationStatus(connector, documentIds);
      }
    },

    isMigrationEnabled: function() {
      return RestResources.getD2Options().is_markup_migration_to_iv_enabled;
    },

    startPoolingMigrationStatus: function(connector, documentIds) {
      this.migrationStatusTimer = setInterval(function () {
        iViewerUtils.getMarkupMigrationStatusByObjectIds(connector,documentIds).done(function(statusData) {
          if(this.isMigrationStatusComplete(statusData)) {
            this.displayMigrationStatus(iViewerUtils.migrationStatusComplete, connector, documentIds);
            clearInterval(this.migrationStatusTimer);
          } else if(this.isMigrationStatusFailed(statusData)) {
            this.displayMigrationStatus(iViewerUtils.migrationStatusFailed, connector, documentIds);
            clearInterval(this.migrationStatusTimer);
          } else if(this.isMigrationStatusTitleUpdateFailed(statusData)) {
             this.displayMigrationStatus(iViewerUtils.migrationStatusTitleUpdateFailed, connector, documentIds);
             clearInterval(this.migrationStatusTimer);
          }
        }.bind(this));
      }.bind(this), 10000);
    },

    isMigrationStatusInProgress: function(objectList) {
      var status = false;
      if(objectList && objectList.markupMigration && objectList.markupMigration.length> 0) {
        status = _.some(objectList.markupMigration, function(object) {
          return object.status === iViewerUtils.migrationStatusInprogress;
        });
      }
      return status;
    },

    isMigrationStatusComplete: function(objectList) {
      var status = false;
      if(objectList && objectList.markupMigration && objectList.markupMigration.length> 0) {
        status = _.every(objectList.markupMigration, function(object) {
          return object.status === iViewerUtils.migrationStatusComplete;
        });
      }
      return status;
    },

    isMigrationStatusFailed: function(objectList) {
      var status = false;
      if(objectList && objectList.markupMigration && objectList.markupMigration.length> 0) {
        status = _.some(objectList.markupMigration, function(object) {
          return object.status === iViewerUtils.migrationStatusFailed;
        });
      }
      return status;
    },

    isMigrationStatusTitleUpdateFailed: function(objectList) {
      var status = false;
      if(objectList && objectList.markupMigration && objectList.markupMigration.length> 0) {
        status = _.some(objectList.markupMigration, function(object) {
          return object.status === iViewerUtils.migrationStatusTitleUpdateFailed;
        });
      }
      return status;
    },

    getDownloadLink: function (node) {
      var url = RestLinkrels.getLink(node.get('links'), RestLinkrels.PREVIEW_URLS);
      if(this.ivWidgetConfiguration.widgetParams["is_override_pdf_config"] === "true") {
        var qParams = {
          format: node.get('aContentType') || node.get('a_content_type')
        }
        url = Url.appendQuery(url, Url.combineQueryString(qParams));
      }
      return url;
    },

    closeViewer: function() {
      var dfd = $.Deferred();
      if(this.api) {
        this.destroy();
        dfd.resolve();
      } else {
        dfd.reject();
      }
      return dfd.promise();
    }
  });
});

csui.define('css!d2/commands/open.plugins/impl/bravaenterprise/textcompare',[],function(){});

csui.define('d2/commands/open.plugins/impl/bravaenterprise/textcompareviewer.view',[
  'module',
  'require',
  'nuc/lib/underscore',
  'nuc/lib/jquery',
  'nuc/lib/marionette',
  'csui/utils/contexts/factories/node',
  'dctmw/utils/rest.resources',
  'nuc/utils/url',
  'd2/controls/behaviors/viewer.masking.behavior',
  'csui/controls/progressblocker/blocker',
  'i18n!d2/commands/open.plugins/nls/localized.strings',
  'css!d2/commands/open.plugins/impl/bravaenterprise/textcompare'
], function (module, require, _, $, Marionette, NodeModelFactory, RestResources, Url, ViewerMaskingBehavior, BlockingView, lang) {
  'use strict';

  var moduleConfig = _.defaults(module.config(), {
    basePath: window.sv.config.releaseLocation + window.sv.config.otherBundlesLocation
  });

  var BravaEnterpriseTextCompareView = Marionette.ItemView.extend({
    className: 'd2-bravaenterprise-textcompare-viewer',

    template:  _.template('<div id="bravaTextCompareRoot"></div>'),

    behaviors: {
      MaskingBehavior: {
        behaviorClass: ViewerMaskingBehavior
      }
    },

    constructor: function BravaEnterpriseTextCompareView(options) {
      options.data || (options.data = {});

      if (!options.model) {
        options.model = options.context.getModel(NodeModelFactory, {
          attributes: {
            id: options.data.id,
            version_number: options.data.version_number || undefined
          }
        });
      }

      Marionette.ItemView.prototype.constructor.call(this, options);

      this._connector = this.model.connector;
      this.nodes = options.previewNodes;
      this.isPreviewMode = options.isPreviewMode;
      this.isEmbeddedPreview = options.isEmbeddedPreview ? options.isEmbeddedPreview : false;
      this.isExpandCollapseButtonAdded = false;
      this.expandCollapseButton = $('<button class="custom-button">');

      this.viewer = null;
      this.isExpanded = false;

      if (!this._connector) {
        throw 'Models must be created with a context in order to obtain a valid connection.';
      }

      if (this.options.blockingParentView) {
        BlockingView.delegate(this, this.options.blockingParentView);
      } else {
        BlockingView.imbue(this);
      }

      this.listenTo(this, 'panel:expand', function(){
        this.isExpanded = true;
        this.expandMode();
      });
      this.listenTo(this, 'panel:collapse', function(){
        this.isExpanded = false;
        this.expandMode();
      });
      this.bravaTextCompareReadyEventCallBackBind = this.bravaTextCompareReadyEventCallBack.bind(this);

      $(window).off('bravaTextCompareReady', this.bravaTextCompareReadyEventCallBackBind).on('bravaTextCompareReady', this.bravaTextCompareReadyEventCallBackBind);
      $(window).on('bravaTextCompareClose', function() {
        if(this.isExpanded) {
          this.trigger('overlay:panel:collapse');
          this.isExpanded = false;
          this.expandMode();
        }
        this.trigger('viewer:close');
        $(window).off('bravaTextCompareReady', this.bravaTextCompareReadyEventCallBackBind);
        this.destroy();
      }.bind(this));
      if(this.isPreviewMode) {
        !this.isAppliedMask() && this.trigger('apply:mask');
      }
    },

    bravaTextCompareReadyEventCallBack: function(e) {
      this.apiName = e.detail;
      this.viewer = window[this.apiName];
      this.fetchAndSetComposition();
    },

    fetchAndSetComposition: function() {
      var me = this;
      var docId = this.nodes.at(0).get("id");
      var compareDocId = this.nodes.at(1).get("id");
      this.blockActions();
      this.getComposition(docId, compareDocId).done(function(response) {
        var responseJson = JSON.parse(response);
        var leftDocument = responseJson.textcomparecomposition[0];
        var rightDocument = responseJson.textcomparecomposition[1];
        var bravaServerUrl = responseJson.bravaserverurl;
        me.setDocumentCompositionIds(bravaServerUrl, leftDocument, rightDocument);
        me._onViewerInit();
        me._addExpandCollapseButton();
        me.unblockActions();
      }).fail(function(){
        me._onViewerApiError("Failed to load viewer");
      });
    },

    _addExpandCollapseButton: function() {
      if(this.isExpandCollapseButtonAdded) {
        return;
      }
      var me = this;

      $(this.expandCollapseButton).on("click", function() {
        if(me.isExpanded) {
          me.isExpanded = false;
          me.trigger('overlay:panel:collapse');
          me.expandMode();
        }
        else {
          me.isExpanded = true;
          me.trigger('overlay:panel:expand');
          me.expandMode();
        }
      });
      $(this.el).find(".ot-ViewerToolbar-left").prepend(this.expandCollapseButton);
      this.expandMode();
      this.isExpandCollapseButtonAdded = true;
    },

    expandMode: function() {
      if(this.isExpanded) {
        $(this.expandCollapseButton).removeClass('expand-viewer-button').addClass('collapse-viewer-button');
        $(this.expandCollapseButton).attr("title", lang.ButtonCollapseViewer);
      }
      else {
        $(this.expandCollapseButton).removeClass('collapse-viewer-button').addClass('expand-viewer-button');
        $(this.expandCollapseButton).attr("title", lang.ButtonExpandViewer);
      }
    },

    getComposition: function(docId, compareDocId) {
      var me = this,
        currentRepo = RestResources.getCurrentRepository().get('name'),
        href = Url.combine(me._connector.connection.url, "repositories", currentRepo, "bravaenterprise", "compare", "text"),
        qParams = {
          docId: docId,
          compareDocId: compareDocId
        };

      href = Url.appendQuery(href, Url.combineQueryString(qParams));

      return $.ajax(me._connector.extendAjaxOptions({
        url: href,
        type: 'GET'
      }));
    },

    setDocumentCompositionIds: function(bravaServerURL, leftDocument, rightDocument) {
      this.viewer.setDocumentCid(bravaServerURL,
        leftDocument['documentUrl'],
        leftDocument['compositionid'],
        leftDocument['filename'],
        leftDocument['position']
      );
      this.viewer.setDocumentCid(bravaServerURL,
        rightDocument['documentUrl'],
        rightDocument['compositionid'],
        rightDocument['filename'],
        rightDocument['position']
      );
    },

    onShow: function() {
      this._loadViewer();
    },

    _loadViewer: function () {
      var me = this;
      csui.require([
        'css!igc/html-text-compare/main'
      ], function loadScripts() {
        var viewerScript = moduleConfig.basePath + '/igc/html-text-compare/main.js',
          scriptElement = document.createElement("script");

        scriptElement.type = "text/javascript";
        scriptElement.src = viewerScript;
        scriptElement.id = 'Brava-Text-Compare-Script';
        $(me.el).append(scriptElement);
      }, function() {
        this._onViewerApiError("HTML Client file load failed");
      });
    },

    _onViewerApiError: function(error) {
      this.trigger('viewer:error', error);
    },

    _onViewerInit: function() {
      this.trigger('viewer:init');
    },

    reloadViewer: function() {
      this.fetchAndSetComposition();
    },

    onDestroy: function () {
      $(window).off('bravaTextCompareReady', this.bravaTextCompareReadyEventCallBackBind);
      this.isAppliedMask() && this.trigger('remove:mask');
    },

    closeViewer: function() {
      var dfd = $.Deferred();
      this.isAppliedMask() && this.trigger('remove:mask');
      if(this.viewer) {
        this.destroy();
        dfd.resolve();
      } else {
        dfd.reject();
      }

      return dfd.promise();
    }
  });

  return BravaEnterpriseTextCompareView;
});

csui.define('css!d2/commands/open.plugins/impl/bravaenterprise/graphicalcompare',[],function(){});

csui.define('d2/commands/open.plugins/impl/bravaenterprise/graphicalcompareviewer.view',[
  'module',
  'require',
  'nuc/lib/underscore',
  'nuc/lib/jquery',
  'nuc/lib/marionette',
  'csui/utils/contexts/factories/node',
  'dctmw/utils/rest.resources',
  'nuc/utils/url',
  'd2/controls/behaviors/viewer.masking.behavior',
  'csui/dialogs/modal.alert/modal.alert',
  'd2/commands/open.plugins/impl/markup.migration/view',
  'd2/controls/globalmessage/globalmessage',
  'd2/utils/format.utils',
  'i18n',
  'i18n!d2/commands/open.plugins/nls/localized.strings',
  'd2/commands/open.plugins/impl/iviewer/utils',
  'css!d2/commands/open.plugins/impl/bravaenterprise/graphicalcompare'
], function (module, require, _, $, Marionette, NodeModelFactory, RestResources, Url, ViewerMaskingBehavior,
             ModalAlert, markupMigrationView, GlobalMessage, FormatUtils, i18n, lang, iViewerUtils) {
  'use strict';

  var moduleConfig = _.defaults(module.config(), {
    basePath: window.sv.config.releaseLocation + window.sv.config.otherBundlesLocation
  });

  var BravaEnterpriseView = Marionette.ItemView.extend({
    className: 'd2-bravaenterpriseviewer',

    template: _.template('<div id="migrationInfo" class="migration-info binf-hidden"></div>'),

    behaviors: {
      MaskingBehavior: {
        behaviorClass: ViewerMaskingBehavior
      }
    },

    constructor: function BravaEnterpriseView(options) {
      options.data || (options.data = {});

      if (options.collection) {
        throw 'Collection viewing is not supported yet.';
      }

      if (!options.model) {
        options.model = options.context.getModel(NodeModelFactory, {
          attributes: {
            id: options.data.id,
            version_number: options.data.version_number || undefined
          }
        });
      }

      Marionette.ItemView.prototype.constructor.call(this, options);

      this.clientLoadData = null;

      this._connector = this.model.connector;
      this.nodes = options.previewNodes;
      this.isPreviewMode = options.isPreviewMode;
      this.isEmbeddedPreview = options.isEmbeddedPreview ? options.isEmbeddedPreview : false;
      this.isExpanded = false;
      this.expandButtonTooltip = lang.ButtonExpandViewer;
      this.collapseButtonTooltip = lang.ButtonCollapseViewer;
      this.expandIcon = 'data:image/svg+xml;base64,';
      this.collapseIcon = 'data:image/svg+xml;base64,';

      if (!this._connector) {
        throw 'Models must be created with a context in order to obtain a valid connection.';
      }

      this.listenTo(this, 'panel:expand', function(){
        this.isExpanded = true;
        this.expandMode();
      });
      this.listenTo(this, 'panel:collapse', function(){
        this.isExpanded = false;
        this.expandMode();
      });
      this.dirtyMarkupCount = 0;
      if(this.isPreviewMode) {
        !this.isAppliedMask() && this.trigger('apply:mask');
      }
    },

    ui: {
      markupMigration: '#migrationInfo'
    },

    onChangeModel: function () {
      if (this.model.hasChanged('id') || this.model.hasChanged('version_number')) {
        this.render();
      }
    },

    onShow: function(){
      this.fetchAndLoadViewer();
    },

    fetchAndLoadViewer: function () {
      if (this.nodes.length < 2) {
        return;
      }
      if(this.clientLoadData) {
        this._loadViewer();
        return;
      }
      var me = this,
        currentRepo = RestResources.getCurrentRepository().get('name'),
        currentUser = RestResources.getCurrentUser().get('name'),
        documentId = this.nodes.at(0).get("id"),
        tzoffset = FormatUtils.getTimezoneOffset(),
        el = me.el,
        elId = el.getAttribute('id'),
        href = Url.combine(me._connector.connection.url, "repositories", currentRepo, "bravaenterprise", "getClientLoadData"),
        qParams = {
          repo: currentRepo,
          log: currentUser,
          docid: documentId,
          tzoffset: tzoffset
        };

      if(this.isPreviewMode) {
        qParams['mode'] = 'preview';
      }

      href = Url.appendQuery(href, Url.combineQueryString(qParams));

      if (!elId) {
        elId = 'd2-bravaenterpriseviewer' + (new Date().getTime());
        el.setAttribute('id', elId);
      }

      $.ajax(me._connector.extendAjaxOptions({
        url: href,
        type: 'GET',
        success: function (data) {
          data = JSON.parse(data);
          me.clientLoadData = data;
          me._loadViewer();
        },
        error: function (error) {
          me.destroy();
          if (error.message){
            GlobalMessage.showMessage("error", error.message, undefined, {});
          }
        }
      }));
    },

    _loadViewer: function () {
      var me = this,
        htmlViewerConfigUrl = this._getHtmlViewerConfigUrl();
        me.checkForMigration(me.nodes.at(0).get("id"), me.nodes.at(1).get("id"));
      if(me.viewer) {
        me.ignoreNextClientClosedEvent = true;
        me.closeViewer().always(me._loadViewer.bind(me));
      }
      csui.require([
        'igc/HTML/html-clients'
      ],function loadScripts() {
        require([
          'igc/HTML/' + me.clientLoadData.htmlClientFactory
        ], function createContent() {
          var viewer = window.brava.htmlClients.create(me.clientLoadData.htmlClientFactory, {
            path: moduleConfig.basePath + '/igc/HTML',
            container: me.el.getAttribute('id'),
            locale: (i18n.settings.locale === 'iw') ? 'he' : i18n.settings.locale,
            clientType: "compare",
            logLevel: "all",
            isCrossOrigin: me.clientLoadData.isCrossOrigin,
            corsServersEntries: me.clientLoadData.corsServersEntries,
            height: "100%",
            width: "100%",
            nodeType: "iframe",
            signedConfigUrl: htmlViewerConfigUrl,
            xmlPostType: "text/xml",
            requestHeaders: me._getSharedHeaderParams(),
            useCompatibilityPrint: true
          });

          viewer.then(function (api) {
            me.viewer = api;
            api.on('ClientClosed', function () {
              if(me.ignoreNextClientClosedEvent === true) {
                me.ignoreNextClientClosedEvent = false;
              } else {
                me.trigger('viewer:close');
                me.destroy();
              }
            });

            api.on('ClientClosedOnStartup', function () {
              me.destroy();
            });

            api.on('DocumentVisible', function () {
              if(me.isPreviewMode === true) {
                me._addCustomCloseButton(api);
                me._addCustomExpandCollapseButton(api);
              }
            });

            api.on('NewDocumentVisible', function(){
              me._onViewerInit();
            });

            api.on('MarkupDirty', function (e) {
              if(e.content && !e.content.fromErrorOrCancel) {
                me.dirtyMarkupCount++;
              }
            });

            api.on('MarkupSaved', function(/*args*/){
              me.dirtyMarkupCount--;
            });

            api.on('MarkupEditClosed', function(/*args*/) {
              me.dirtyMarkupCount > 0 && me.dirtyMarkupCount--;
            });

            api.on('LoadingError', function () {
              me.isAppliedMask() && me.trigger('remove:mask');
              // enable close button, should be removed when it is fixed from viewer side
              $('#' + me.el.getAttribute('id') + ' iframe').contents().find('#closeOnStartupButton').css({display:"block"});
            });
          });

        }, function() {
          me._onViewerApiError("HTML Client Factory load error");
        });
      }, function() {
        me._onViewerApiError("HTML Client file load failed");
      });
    },

    _getHtmlViewerConfigUrl: function() {
      var tzoffset = FormatUtils.getTimezoneOffset(),
        currentRepo = RestResources.getCurrentRepository().get('name'),
        currentUser = RestResources.getCurrentUser().get('name'),
        href = Url.combine(this._connector.connection.url, "repositories", currentRepo, "bravaenterprise", "compare", "graphical"),
        docId = this.nodes.at(0).get("id"),
        compareDocId = this.nodes.at(1).get("id"),
        qParams = {
          repo: currentRepo,
          docId: docId,
          compareDocId: compareDocId,
          log: currentUser,
          tzoffset: tzoffset
        };

      href = Url.appendQuery(href, Url.combineQueryString(qParams));

      return href;
    },

   checkForMigration: function(docId, compareDocId) {
        var me = this;
        iViewerUtils.getMarkupMigrationStatusByObjectIds(me.model.connector,[docId, compareDocId]).done(function(statusData) {
          if(statusData && statusData.markupMigration && statusData.markupMigration.length> 0) {
            me.displayMigrationBannerInfo("GRAPHICAL_COMPARE");
          } else {
            me.hideMigrationStatusBar();
          }
        });
    },

    hideMigrationStatusBar: function() {
          $(this.el).find(this.ui.markupMigration).addClass('binf-hidden');
          $(this.el).find(this.ui.markupMigration).removeClass('with-migration-status');
        },

    displayMigrationBannerInfo: function(viewerType) {
      var region = new Marionette.Region({el: this.ui.markupMigration});
      var view = new markupMigrationView({
        viewerType: viewerType,
      });
      this.showMigrationStatusBar();
      region.show(view);
    },

     showMigrationStatusBar() {
          $(this.el).find(this.ui.markupMigration).removeClass('binf-hidden');
          $(this.el).find(this.ui.markupMigration).addClass('with-migration-status');
        },

    _getSharedHeaderParams: function () {
      var headers = {};
      this.model.connector.authenticator.setAuthenticationHeaders(headers);
      headers["Accept-Language"] = (i18n.settings.locale === 'iw') ? 'he' : i18n.settings.locale;
      return headers;
    },

    _addCustomCloseButton: function(bravaApi) {
      var me = this;
      this._addCustomButton(bravaApi, {
        varName: 'customCloseButton',
        tooltip: lang.ButtonCloseViewer,
        icon: 'data:image/svg+xml;base64,',
        hoverIcon: 'data:image/svg+xml;base64,',
        activeIcon: 'data:image/svg+xml;base64,',
        placement: {
          toolbarRegion: 'End',
          buttonPosition: 'Last'
        },
        pinWidget: true,
        cssStyle: 'background-color: transparent;',
        handler: function customClick(e) {
          e = e ? $.Event(event) : e;
          me.checkDirtyMarkupAndClose(e);
        }
      });
    },

    saveMarkupConfirmDialog: function() {
      var deferred = $.Deferred();
      var buttonOptions = {
        labelYes: lang.CompareSaveMarkupDialogButtonYes,
        showNo: false,
        showCancel: true
      };

      ModalAlert.confirmQuestion(function (result) {
        if (result === true) {
          deferred.resolve();
        }
        if (result === false) {
          deferred.reject();
        }
      }, lang.CompareSaveMarkupDialogBody, lang.SaveMarkupDialogHeader, {
        buttons: buttonOptions,
        modalClass: 'd2-be-sm-dialog'
      });

      return deferred.promise();
    },

    checkDirtyMarkupAndClose: function(e) {
      var me = this;
      if(me.dirtyMarkupCount) {
        this.saveMarkupConfirmDialog().done(function() {
          me.viewer.closeMarkupFile({forceClose: true}).then(function() {
            me.viewer.closeMarkupFile1({forceClose: true}).then(function() {
              me.isAppliedMask() && me.trigger('remove:mask');
              me.dirtyMarkupCount = 0;
              me.doClose(e);
            });
          });
        })
      }
      else {
        me.doClose(e);
      }
    },

    doClose: function(e) {
      var me = this;
      if(this.isExpanded) {
        this.trigger('overlay:panel:collapse');
        this.isExpanded = false;
        this.expandMode();
      }
      this.closeViewer().done(function() {
        me.viewer = null;
        me.trigger('viewer:close', e);
        me.isAppliedMask() && me.trigger('remove:mask');
      }).fail(function() {
        me.trigger('viewer:close', e);
      });
    },

    _addCustomExpandCollapseButton: function(bravaApi) {
      var me = this;
      this._addCustomButton(bravaApi, {
        varName: 'customExpandCollapseButton',
        tooltip: me.expandButtonTooltip,
        icon: me.isExpanded ? me.collapseIcon : me.expandIcon,
        placement: {
          toolbarRegion: 'Start',
          buttonPosition: 'First'
        },
        pinWidget: true,
        cssStyle: 'margin-left: -15px;background-color: #3F4950;',
        handler: function customClick(e) {
          e = e ? $.Event(event) : e;
          if (!me.isExpanded) {
            me.trigger('overlay:panel:expand', e);
            me.isExpanded = true;
            me.expandMode();
          } else {
            me.trigger('overlay:panel:collapse');
            me.isExpanded = false;
            me.expandMode();
          }
        }
      });
    },

    _addCustomButton: function (bravaApi, options) {
      /*var me = this,
        setBtnBg = function (e, icon) {
          var elId = 'customBravaWidgetId_' + e.targetId,
            btnEl = $('#' + me.el.getAttribute('id') + ' iframe').contents().find('.dijitButton[widgetId=' + elId + ']');
          btnEl.css({
            backgroundImage: 'url("' + icon + '")'
          });
        };*/
      if (bravaApi[options.varName] === undefined) {
        var optionsCssStyle = options.cssStyle ? options.cssStyle : '';

        bravaApi[options.varName] = bravaApi.addCustomButton({
          type: 'Button',
          showLabel: false,
          toolTip: options.tooltip,
          icon: options.icon,
          cssStyleAdjustments: optionsCssStyle + 'background-position:center; background-size:24px 24px ' + (options.applyRTLStyleForIcon === true && i18n.settings.rtl ? '; transform: scaleX(-1)' : ''),
          container: {
            name: 'TaskBar',
            placement: options.placement ? options.placement : {
              toolbarRegion: 'Start',
              index: options.position
            }
          },
          pinWidget: (options.pinWidget === true),
          eventHandlers: {
            click: options.handler
          }
        });
      }
    },

    _onViewerApiError: function(error) {
      this.isAppliedMask() && this.trigger('remove:mask');
      this.trigger('viewer:error', error);
    },

    expandMode: function() {
      var me = this;
      this.viewer['customExpandCollapseButton'].then(function(buttonData) {
        var btnEl = $('#' + me.el.getAttribute('id') + ' iframe').contents().find('.dijitButton[widgetId=' + buttonData.id + ']');
        var btnInnerEl = $('#' + me.el.getAttribute('id') + ' iframe').contents().find('#'+buttonData.id);
        if(me.isExpanded) {
          btnEl.css({
            backgroundImage: 'url("' + me.collapseIcon + '")'
          });
          btnInnerEl.prop('title', me.collapseButtonTooltip);
        }
        else {
          btnEl.css({
            backgroundImage: 'url("' + me.expandIcon + '")'
          });
          btnInnerEl.prop('title', me.expandButtonTooltip);
        }
      });
    },

    _onViewerInit: function() {
      this.trigger('viewer:init');
    },

    reloadViewer: function() {
      this.fetchAndLoadViewer();
    },

    onDestroy: function () {
      this.isAppliedMask() && this.trigger('remove:mask');
    },

    closeViewer: function() {
      var dfd = $.Deferred();
      this.isAppliedMask() && this.trigger('remove:mask');
      if(this.viewer) {
        this.viewer.closeViewer({allowCancel: false}).then(function(){
          dfd.resolve();
        }, function(){
          this._onViewerApiError();
          dfd.reject();
        }.bind(this));
      } else {
        dfd.reject();
      }

      return dfd.promise();
    }
  });

  return BravaEnterpriseView;
});

