csui.define('d2/commands/workflow/allworkflows.queryform',[
  'require',
  'nuc/lib/underscore',
  'nuc/lib/jquery',
  'csui/models/command',
  'dctmw/controls/mixins/view.state/widget.view.state.mixin',
  'd2/utils/constants',
  'dctmw/utils/user.preference.storage',
  'd2/utils/contexts/factories/widget.view.state.factory',
  'i18n!d2/widgets/workflow.queryform/impl/nls/lang'
], function (require, _, $, CommandModel, WidgetViewStateMixin, constants, userPreference, WidgetViewStateModelFactory, lang) {
  'use strict';

  var AllWorkflowsQueryForm = CommandModel.extend({

    defaults: {
      signature: 'D2-AllWorkflowsQueryForm'
    },

    enabled: function () {
      return true;
    },

    execute: function (options) {
      var me = this;
      me.options = options || {};
      me.context = me.options.context;
      me._openWizard();
    },

    _openWizard: function () {
      var action = this;
      csui.require([
        'd2/controls/stepper.wizard/stepper.wizard.view'
      ], function (StepperWizard) {
        action._createWizardSteps().then(function (wizardSteps) {
          action._wizard = new StepperWizard({steps: wizardSteps, className: 'd2-wf-query-search-form', data: {}});
          action._wizard.show();
        });
      });
    },

    _createWizardSteps: function () {
      var me = this, dfd = $.Deferred();
      csui.require([
        'd2/widgets/workflow.queryform/impl/workflow.query.form.panel'
      ], function (WFQueryFormPanel) {
        var step = {
          id: 'wfqueryform',
          title: me.options.title,
          viewClass: WFQueryFormPanel,
          viewOptions: {
            context: me.options.context,
            widgetName: me.options.widgetName,
            workflowsReportingType: me.options.workflowsReportingType,
            'document-id_storeContainer': true,
            'document-id_restoreContainer': true
          },
          buttons: [
            {
              id: 'next',
              toolTip: lang.search,
              label: lang.search,
              disabled: function () {
                return this.searchButtonDisabled;
              },
              clickHandler: function () {
                this.validateForm(true,false).done(_.bind(function(isValid){
                  if(isValid){
                    var formValues, qParamData;
                    formValues = this.getFormValues();
                    if (formValues && !_.isEmpty(formValues)) {
                      qParamData = formValues ? JSON.stringify(formValues) : undefined;
                      var widgetViewStateModel = me.options.context.getObject(WidgetViewStateModelFactory);
                      widgetViewStateModel && widgetViewStateModel.set('qform-param', qParamData);
                      userPreference.saveLocalStorePreference(userPreference.StorageTypes.SEARCH_PANEL_VISIBILITY, constants.WidgetId.WORKFLOWS, true);
                      me.setViewStateWidgetName(me.options.widgetName);
                      me.options.context.viewStateModel.set('enabled', true);
                      me.options.applicationScope.set('id', 'allworkflows');
                      me.trigger('open:workflows:perspective');
                      me._wizard.close();
                    }
                  }
                },this));
              }
            }
          ]
        };
        var steparr = [];
        steparr.push(step);
        dfd.resolve(steparr);
      });
      return dfd.promise();
    }

  });
  _.extend(AllWorkflowsQueryForm.prototype, WidgetViewStateMixin);
  return AllWorkflowsQueryForm;
});

csui.define('d2/commands/viewer/direct.view.link',[
  'require',
  'nuc/lib/underscore',
  'nuc/lib/jquery',
  'd2/utils/constants',
  'csui/models/command',
  'csui/utils/commandhelper',
  'd2/utils/server.query.utils',
  'd2/utils/widget.constants',
  'dctmw/utils/client.location'
], function(require, _, $, constants, CommandModel, CommandHelper, serverQueryUtils, widgetConstants, clientLocation){
  'use strict';

  const DirectViewLink = CommandModel.extend({
    defaults: {
      signature: 'D2-DirectView',
      command_key: 'D2-DirectView',
      scope: 'single'
    },

    enabled: function(status) {
      if(status && status.context && status.context.isEmbeddedMode === true) {
        return false;
      }
      var node = CommandHelper.getJustOneNode(status), enable = false,
          viewer = (status.data && status.data.viewer) ? status.data.viewer : '';
      if (node && status.nodes.length === 1) {
        enable = _.contains([constants.Types.DOCUMENT], node.get('type'));
        if(enable && !_.isEmpty(viewer)) {
          if(!(serverQueryUtils.getWidgetConfig(widgetConstants.D2.BRAVACSR, viewer) ||
              serverQueryUtils.getWidgetConfig(widgetConstants.D2.BRAVAENTERPRISE, viewer) ||
              serverQueryUtils.getWidgetConfig(widgetConstants.D2.BRAVAIV, viewer))) {
            enable = false;
          }
        }
      }
      return enable;
    },

    execute: function(status/*, options*/) {
      var viewer = (status.data && status.data.viewer) ? status.data.viewer : '';
      const dfd = $.Deferred();
      var link = document.createElement("a");
      link.target = "_blank";
      if(viewer) {
        link.href = clientLocation.modularizeFragment(`viewer?node=${status.nodes.at(0).get('id')}&viewer-name=${viewer}`);
      } else {
        link.href = clientLocation.modularizeFragment(`viewer?node=${status.nodes.at(0).get('id')}`);
      }
      link.click();

      return dfd.resolve().promise();
    }
  });

  return DirectViewLink;
});


csui.define('d2/commands/advanced.search',[
  'require',
  'nuc/lib/jquery',
  'nuc/lib/underscore',
  'csui/controls/globalmessage/globalmessage',
  'csui/utils/commandhelper',
  'csui/models/command',
  'csui/utils/contexts/factories/connector',
  'd2/utils/advanced.search.utils',
  'd2/utils/search.utils',
  'dctmw/utils/utils',
  'i18n!d2/commands/nls/localized.strings'
], function (require, $, _, GlobalMessage, CommandHelper, CommandModel, ConnectorFactory, AdvancedSearchUtils, searchUtils, utils, lang) {
  'use strict';

  return CommandModel.extend({

    defaults: {
      signature: 'D2-AdvancedSearch',
      command_key: 'D2-AdvancedSearch',
      name: lang.AdvancedSearchCommandName,
      scope: 'single'
    },

    _fetchSearchLocations: function (options) {
      var deferred = $.Deferred();

      AdvancedSearchUtils.getSearchLocations({
        connector: options.connector,
        searchConfig: options.searchConfig
      }).done(function (linearSearchLocations) {
        deferred.resolve(AdvancedSearchUtils.getSearchLocationsTreeStructure({
          linearSearchLocations: linearSearchLocations,
          searchConfig: options.searchConfig
        }));
      }).fail(function (xhr, message, statusText) {
        deferred.reject(xhr, message, statusText);
      });

      return deferred.promise();
    },

    _fetchSearchConfig: function (options) {
      var deferred = $.Deferred();
      searchUtils.getSearchConfiguration({connector: options.connector}).done(function(searchConfig){
        if(searchConfig!==null){
          deferred.resolve(searchConfig);
        }
        else{
          GlobalMessage.showMessage("error",lang.noSearchConfiguration);
          deferred.reject();
        }
      }).fail(deferred.reject);

      return deferred.promise();
    },

    execute: function (status, options) {
      options = options || {};
      var deferred = $.Deferred();

      this._executeAdvancedSearch(status, options).done(function (message) {
        message && GlobalMessage.showMessage('success', message);
        deferred.resolve();
      }).fail(deferred.reject);

      return deferred.promise();
    },

    _executeAdvancedSearch: function (status, options) {
      var me = this;

      options.connector = status.context.getObject(ConnectorFactory);
      _.extend(options, status);

      me._blockActions();
      return me._fetchSearchConfig(options).then(function (searchConfig) {
        options.searchConfig = searchConfig;
        options.searchConfig.searchOptions = {
          searchTerm: options.searchTerm,
          searchOption: options.searchOption,
          currentNode: options.currentNode
        };
        me._unblockActions();
        return me._openWizard(options);
      }).catch(function (xhr, message, statusText) {
        me._unblockActions();
        if (xhr === 'close' || (!message && !statusText)) {
          return $.Deferred().reject().promise();
        } else {
          GlobalMessage.showMessage('error', utils.parseAjaxErrorAsString(xhr, statusText, message));
          return $.Deferred().reject(xhr, message, statusText).promise();
        }
      });
    },

    _openWizard: function (options) {
      var deferred = $.Deferred();

      csui.require([
        'd2/dialogs/advanced.search/advanced.search.dialog'
      ], function (AdvancedSearchDialog) {
        var advancedSearchDialog = new AdvancedSearchDialog({
          searchConfig: options.searchConfig,
          context: options.context,
          connector: options.connector,
          savedSearchModel: options.savedSearchModel,
          search_in_storeContainer: true
        });
        advancedSearchDialog.showAdvancedSearchWizard().done(deferred.resolve).fail(deferred.reject);
      });

      return deferred.promise();
    },

    _blockActions: function (view) {
      CommandHelper.blockD2ViewActions(view);
    },

    _unblockActions: function (view) {
      CommandHelper.unblockD2ViewActions(view);
    }
  });
});

csui.define('d2/commands/aviator/add.assignments',[
  'nuc/lib/jquery',
  'nuc/lib/underscore',
  'csui/models/command',
  'nuc/models/node/node.model',
  'd2/utils/constants',
  'i18n!d2/commands/nls/localized.strings'
], function ($, _, CommandModel, NodeModel, constants, lang) {
  'use strict';

  const AddAssignments = CommandModel.extend({
    defaults: {
      signature: 'Aviator-AddAssignment',
      command_key: 'Aviator-AddAssignment',
      name: lang.CommandAviatorAddAssignment,
      scope: 'single'
    },

    enabled: function (status/*, options*/) {
      return (!status.nodes) || !status.nodes.length;
    },

    execute: function (status/*, options*/) {
      var containerNode = new NodeModel(undefined, { context: status.context, connector: status.collection.connector }),
        selectedValues = status.collection.allModels.map(model => model.get('id'));

      this.displayContentAssist(status, containerNode, selectedValues)
        .done(models => status.collection.addNodeModels(models));
      return $.Deferred().resolve().promise();
    },

    displayContentAssist: function (status, container, selectedValues) {
      var deferred = $.Deferred();
      /* DTWO-119106: From 24.4, there is no limit on max files and folders for av4r.
       Uncomment, it when we have to limit files and folders based on license or some other metrics/config */
      
       // var aviatorConfig = status.originatingView && status.originatingView.options && status.originatingView.options.config;

      csui.require(['d2/dialogs/target.browse/target.browse'], function (NodePicker) {
        var pickerOptions = {
          dialogTitle: lang.AviatorContentAssistTitle,
          connector: status.collection.connector,
          container: container,
          initialContainer: container,
          context: status.context,
          selectMultiple: true,
          includeBrowse: true,
          globalSearch: false,
          includeFavorites: false,
          includeRelatedFiles: false,
          subTypeFilters: ['dm_folder'],
          locationSelector: false,
          selectType: 'typeName',
          selectTypeValue: constants.Types.FOLDER,
        };

        pickerOptions.disabledNodeIds = selectedValues || [];
        pickerOptions.disabledSelectionState = true;
        // DTWO-119106
        // pickerOptions.maxItemCanSelect = aviatorConfig.get("av4r_max_assignments") - pickerOptions.disabledNodeIds.length;

        pickerOptions.storeContainer = true;
        pickerOptions.restoreContainer = true;
        pickerOptions.dataId = constants.StorageKey.AVIATOR_ASSIGNMENT_ADD + constants.StorageKey.ANCESTOR_INFO;

        pickerOptions.startLocations = [];
        if (pickerOptions.includeBrowse) {
          pickerOptions.startLocations.push('current.location');
        }
        var nodePicker = new NodePicker(pickerOptions);

        nodePicker.show().done(function (selectedNodes) {
          deferred.resolve(selectedNodes.nodes);
        }).fail(function () {
          deferred.reject('close');
        });
      }, deferred.reject);

      return deferred.promise();
    }
  });

  return AddAssignments;
});


csui.define('d2/commands/aviator/goto.location',[
  'nuc/lib/jquery',
  'nuc/lib/underscore',
  'csui/models/command',
  'csui/utils/commandhelper',
  'csui/utils/node.links/node.links',
  'dctmw/utils/constants',
  'dctmw/utils/utils',
  'i18n!d2/commands/nls/localized.strings'
], function($, _, CommandModel, CommandHelper, nodeLinks, constants, utils, lang){
  'use strict';
  
  const GoToLocation = CommandModel.extend({
    defaults: {
      signature: 'Aviator-GoToLocation',
      command_key: 'Aviator-GoToLocation',
      name: lang.CommandAviatorGotoLocation,
      scope: 'single'
    },
    
    enabled: function(status, options) {
      const node = CommandHelper.getJustOneNode(status);
      const type = node && node.get('type');
      return (type === constants.Types.CABINET || type === constants.Types.FOLDER) && CommandModel.prototype.enabled.call(this, status, options);
    },
    
    execute: function(status, options) {
      const opts = _.extend({}, status, options);
      let node = CommandHelper.getJustOneNode(status);
      if(opts.openParentLocation === true) {
        node = node.parent;
      }
      
      const url = node && nodeLinks.getUrl(node);
      const openInNewTab = opts.newTab !== false;
      const winName = opts.windowName || '_blank';
      const winFeatures = opts.windowFeatures || '';
      
      utils.openUrlInWindow(url, openInNewTab ? window.open('', winName, winFeatures) : null, true, true);
      
      return $.Deferred().resolve().promise();
    }
  });
  
  return GoToLocation;
});

csui.define('d2/commands/aviator/remove.assignments',[
  'nuc/lib/jquery',
  'csui/models/command',
  'csui/utils/commandhelper',
  'i18n!d2/commands/nls/localized.strings',
], function ($, CommandModel, CommandHelper, lang) {
  'use strict';

  const RemoveAssignments = CommandModel.extend({
    defaults: {
      signature: 'Aviator-RemoveAssignment',
      command_key: 'Aviator-RemoveAssignment',
      name: lang.CommandAviatorRemoveAssignment,
      scope: 'multiple'
    },

    execute: function (status/*, options*/) {
      const nodes = CommandHelper.getAtLeastOneNode(status),
        deferred = $.Deferred();
      status.collection.remove(nodes.models);
      // when all nodes are removed, nodespagination view has a logic to adjust the skipCount back to previous page.
      // But when we have only one page, skipCount becomes negative, and pagionation bar will have negative page numbers.
      // look for the logic under the comment "update skipCount when we delete all the items in last page" in smart/.../nodespagination.view
      status.collection.skipCount = Math.max(0, status.collection.skipCount);
      status.collection.fetch({ reload: false }).always(() => deferred.resolve());
      return deferred.promise();
    }
  });

  return RemoveAssignments;
});


csui.define('d2/commands/aviator/reset.config',[
  'require',
  'nuc/lib/jquery',
  'csui/models/command',
  'i18n!d2/commands/nls/localized.strings'
], function(require, $, CommandModel, lang){
  'use strict';
  
  const ResetConfig = CommandModel.extend({
    defaults: {
      signature: 'Aviator-ResetConfig',
      command_key: 'Aviator-ResetConfig',
      name: lang.CommandAviatorResetConfig,
      scope: 'single'
    },
    
    enabled: function(/*status, options*/) {
      return true;
    },
    
    execute: function(status/*, options*/) {
      const dfd = $.Deferred();
      
      csui.require([
        'd2/utils/contexts/factories/aviator.config.model.factory',
        'd2/utils/contexts/factories/aviator.assignments.collection.factory'
      ], function(AviatorConfigModelFactory, AviatorAssignmentsCollectionFactory){
        const context = status.context;
        const configModel = status.container || context.getModel(AviatorConfigModelFactory);
        const assignmentsCollection = status.collection || context.getCollection(AviatorAssignmentsCollectionFactory);
        
        configModel
          .fetch({reload: true, skipSWCache: true})
          .then(()=>{
            return assignmentsCollection.fetch({reload: true, skipSWCache: true});
          })
          .done(dfd.resolve)
          .fail(dfd.reject);
      }, dfd.reject);
      
      return dfd.promise();
    }
  });
  
  return ResetConfig;
});


csui.define('d2/commands/aviator/save.config',[
  'require',
  'nuc/lib/jquery',
  'nuc/lib/underscore',
  'nuc/lib/backbone',
  'dctmw/utils/rest.resources',
  'd2/commands/aviator/reset.config',
  'd2/commands/node.progress.command',
  'd2/utils/constants',
  'd2/utils/rest.linkrels',
  'i18n!d2/commands/nls/localized.strings'
], function (require, $, _, Backbone, RestResources, ResetConfig, NodeProgressCommand,
  constants, RestLinkrels, lang) {
  'use strict';

  const ENABLE_AVIATOR = 'ENABLE',
    DISABLE_AVIATOR = 'DISABLE';

  const SaveConfig = NodeProgressCommand.extend({
    defaults: {
      signature: 'Aviator-SaveConfig',
      command_key: 'Aviator-SaveConfig',
      name: lang.CommandAviatorSaveConfig,
      scope: 'single'
    },

    enabled: function (/*status, options*/) {
      return true;
    },

    execute: function (status/*, options*/) {
      const dfd = $.Deferred();
      csui.require([
        'd2/utils/contexts/factories/aviator.config.model.factory',
        'd2/utils/contexts/factories/aviator.assignments.collection.factory'
      ], (AviatorConfigModelFactory, AviatorAssignmentsCollectionFactory) => {
        const context = status.context;
        status.configModel = status.configModel || context.getModel(AviatorConfigModelFactory);
        status.assignmentsCollection = status.collection || context.getCollection(AviatorAssignmentsCollectionFactory);

        NodeProgressCommand.prototype.execute.apply(this, arguments).then(dfd.resolve, dfd.reject);
      }, dfd.reject);
      return dfd.promise();
    },

    preProcess: function (status/*, options*/) {
      this._prepareStatusNodes(status);
      return this.showConfirmationAlert(status);
    },

    _performActions: function (status/*, options*/) {
      let configModel = status.configModel,
        isAviatorToggled = this._isAviatorToggled(configModel),
        isEnabled = configModel.get('is_enabled'),
        processingMap = { add: false, remove: false, toggle: false },
        abortTasks = _.partial(this._abortTasks, processingMap, isAviatorToggled, status);

      configModel.trigger('av4r:config:save:start')

      processingMap.toggle = isEnabled && isAviatorToggled;
      this._toggleAviatorStatus(status, true)
        .then(() => {
          processingMap.remove = true;
          return this._removeAssignments(status);
        }).then(() => {
          processingMap.add = true;
          return this._addAssignments(status);
        }).then(() => {
          processingMap.toggle = true;
          return this._toggleAviatorStatus(status, false);
        })
        .then(() => this._refreshData(status))
        .catch(() => abortTasks())
        .always(() => configModel.trigger('av4r:config:save:end'));

      return NodeProgressCommand.prototype._performActions.apply(this, arguments);
    },

    _refreshData: function (options) {
      return new ResetConfig().execute(options);
    },

    _abortTasks: function (processingMap, isToggled, status) {
      let idToPromise = status.idToPromise;
      let addPromises = processingMap.add ? [] : Object.values(idToPromise['ADD']),
        removePromises = processingMap.remove ? [] : Object.values(idToPromise['REMOVE']),
        togglePromises = !isToggled ? [] : processingMap.toggle ? [] : [idToPromise['TOGGLE']],
        promises = [...addPromises, ...removePromises, ...togglePromises];

      promises?.forEach(promise => promise.reject(lang.aviatorActionAborted));
    },

    doAction: function (node/*, options*/) {
      return node.promise;
    },

    _prepareStatusNodes: function (status) {
      const
        { assignmentsCollection, configModel } = status,
        isAv4rToggled = this._isAviatorToggled(configModel);

      let idToPromise = { 'ADD': {}, 'REMOVE': {}, 'TOGGLE': null };

      function injectTrackerPromise(action, assignments) {
        return assignments.map(assigment => {
          let prom = $.Deferred();
          assigment.promise = prom;
          assigment.ACTION = action;
          idToPromise[action][assigment.get('id')] = prom;
          return assigment;
        });
      }

      let newAssignments = injectTrackerPromise('ADD', assignmentsCollection.locallyAddedAssignments),
        removedAssignments = injectTrackerPromise('REMOVE', assignmentsCollection.locallyRemovedAssignments),
        nodes = [...removedAssignments, ...newAssignments];


      if (isAv4rToggled) {
        const isEnabled = configModel.get('is_enabled');
        const task = new Backbone.Model({ r_object_type: 'dm_csai_config', name: isEnabled ? lang.progressEnableAviator : lang.progressDisableAvaitor });
        task.promise = $.Deferred();
        idToPromise['TOGGLE'] = task.promise;
        nodes[isEnabled ? 'unshift' : 'push'](task);
      }

      status.idToPromise = idToPromise;
      status.nodes = nodes;
    },

    _isAviatorToggled: function (configModel) {
      return configModel.get('is_enabled') !== configModel.getServerAttribute('is_enabled');
    },

    _toggleAviatorStatus: function (status, processForState) {
      const dfd = $.Deferred(),
        { configModel, context } = status,
        clientState = configModel.get('is_enabled'),
        isToggled = this._isAviatorToggled(configModel);

      if (isToggled && clientState === processForState) {
        const promise = status.idToPromise['TOGGLE'],
          url = RestLinkrels.getLink(configModel.get('links'), RestLinkrels.AVIATOR_GLOBAL_STATUS),
          payload = { status: clientState ? ENABLE_AVIATOR : DISABLE_AVIATOR };

        this.makeAjaxRequest(url, 'PUT', payload, context).then(() => {
          promise.resolve();
          dfd.resolve();
        }, err => {
          let errMessage = err?.responseJSON?.message;
          if (!errMessage) {
            errMessage = clientState ? lang.enableAviatorFailed : lang.disableAviatorFailed;
          }
          promise.reject(errMessage);
          dfd.reject();
        });
      } else {
        dfd.resolve();
      }
      return dfd.promise();
    },

    _addAssignments: function (status) {
      return this._updateAssignmentItems(status, 'POST', status.assignmentsCollection.locallyAddedAssignments, false)
    },

    _removeAssignments: function (status) {
      return this._updateAssignmentItems(status, 'DELETE', status.assignmentsCollection.locallyRemovedAssignments, true)
    },

    _updateAssignmentItems: function (status, method, models, isRemove) {
      let dfd = $.Deferred(),
        processResponseItems = _.partial(this._processResponseItems, status.assignmentsCollection, status, isRemove);

      this._syncState(method, { context: status.context, models })
        .then(response => {
          const hasError = processResponseItems(response.items || []);
          hasError ? dfd.reject() : dfd.resolve();
        }, err => {
          this._abortTasksInAction(isRemove ? 'REMOVE' : 'ADD', status, err);
          dfd.reject();
        });
      return dfd.promise();
    },

    _abortTasksInAction: function (action, status, err) {
      const message = err.responseJSON.message || lang.aviatorActionFailed,
        itemsMap = status.idToPromise[action];
      Object.keys(itemsMap).forEach(id => itemsMap[id]?.reject(message));
    },

    _processResponseItems: function (collection, status, isRemove, items) {
      let action = isRemove ? 'REMOVE' : 'ADD',
        idToPromiseMap = status.idToPromise[action],
        hasError = false;
      items.forEach(item => {
        let id = item.r_object_id,
          promise = idToPromiseMap[id],
          err = item['rest-error'];
        if (err) {
          hasError = true;
          err = _.isArray(err) ? err[0] : err;
          promise.reject(err?.message || lang.aviatorActionFailed);
        } else {
          isRemove ? collection.removeLocallyDeletedAssignment(id) :
            collection.removeLocallyAddedAssignment(id);
          promise.resolve();
        }
      });
      return hasError;

    },

    _syncState: function (method, { context, models }) {
      const dfd = $.Deferred();
      const ids = models.map(model => model.get('id'));

      if (ids.length) {
        const url = RestLinkrels.getLink(RestResources.getCurrentRepository().get('links'), RestLinkrels.AVIATOR_MARKER),
          payload = { items: ids.map(id => { return { r_object_id: id }; }) };

        this.makeAjaxRequest(url, method, payload, context).then(dfd.resolve, dfd.reject);
      } else {
        dfd.resolve([])
      }
      return dfd.promise();
    },

    makeAjaxRequest: function (url, method, payload, context) {
      const dfd = new $.Deferred();
      $.ajax(context.getObject('connector').extendAjaxOptions({
        url: url,
        type: method,
        contentType: constants.MediaTypes.JSON,
        data: JSON.stringify(payload),
        success: dfd.resolve,
        error: dfd.reject
      }));
      return dfd.promise();
    },

    showConfirmationAlert: function (status) {
      var dfd = $.Deferred();

      csui.require(['d2/dialogs/modal.aviator.summary/aviator.summary.dialog'], ModalAlert => {
        ModalAlert.showConfirmationDialog(status).then(dfd.resolve, dfd.reject);
      }, dfd.reject);
      return dfd.promise();
    },

    getMessageOptions: function () {
      const processing = lang.aviatorConfigSaveProcessing,
        av4rConfigSaveSuccess = lang.aviatorConfigSaveSuccessMessage,
        av4rConfigSaveFailed = lang.aviatorConfigSaveFailureMessage;
      return {
        oneFilePending: processing,
        multiFilePending: processing,
        oneFileSuccess: av4rConfigSaveSuccess,
        multiFileSuccess: av4rConfigSaveSuccess,
        oneFileFailure: av4rConfigSaveFailed,
        multiFileOneFailure: av4rConfigSaveFailed,
        multiFileFailure: av4rConfigSaveFailed,
        actionType: 'AVIATOR_CONFIG_SAVE',
        enableCancel: false
      };
    }
  });

  return SaveConfig;
});


