csui.define('d2/commands/mip/save.config',[
    'require',
    'nuc/lib/jquery',
    'nuc/lib/underscore',
    'nuc/lib/backbone',
    'dctmw/utils/rest.resources',
    'd2/commands/mip/reset.config',
    'csui/models/command',
    'd2/controls/globalmessage/globalmessage',
    'dctmw/utils/utils',
    'i18n!d2/widgets/admin/mip.config/impl/nls/lang'
], function (require, $, _, Backbone, RestResources, ResetConfig, CommandModel,GlobalMessage,Utils,lang) {
    'use strict';

    const SaveConfig = CommandModel.extend({
        defaults: {
            signature: 'Mip-SaveConfig',
            command_key: 'Mip-SaveConfig',
            name: lang.commandMipSaveConfig,
            scope: 'single'
        },

        enabled: function (/*status, options*/) {
            return true;
        },

        execute: function (status/*, options*/) {
            const dfd = $.Deferred();
            csui.require([
                'd2/utils/contexts/factories/mip.config.model.factory'
            ], (MipConfigModelFactory) => {
                const context = status.context;
                status.configModel = status.configModel || context.getModel(MipConfigModelFactory);
                let configModel = status.configModel;
                delete configModel.attributes['is_enabled'];
               let changedAttr= this._findDifference(configModel);
                configModel.save(changedAttr,{patch:!configModel.isNew()}).done(function () {
                    GlobalMessage.showMessage('success', lang.saveSuccessMessage);
                    dfd.resolve;
                }).fail(function (xhr) {
                    let errDetails = Utils.parseAjaxError(xhr);
                    GlobalMessage.showMessage('error', errDetails.message, errDetails.details);
                    dfd.reject;
                });

            }, dfd.reject);
            return dfd.promise();
        },

        _findDifference: function (configModel) {
            let changeAttribute = {};
            Object.keys(configModel.attributes).forEach(key => {
                if (!_.isEqual(configModel.getServerAttribute(key), configModel.attributes[key])) {
                    changeAttribute[key] = configModel.attributes[key];
                }
            });
            return changeAttribute;
        }

    });

    return SaveConfig;
});


csui.define('d2/commands/content-annotations',[
  'nuc/lib/jquery',
  'nuc/lib/underscore',
  'dctmw/utils/rest.resources',
  "csui/models/command",
  'csui/utils/commandhelper',
  'd2/utils/rest.linkrels',
  'd2/utils/constants',
  'dctmw/utils/utils',
  'd2/controls/globalmessage/globalmessage',
  'i18n!d2/server.adaptors/models/impl/nls/lang'
], function ($,_, RestResources, CommandModel, CommandHelper, RestLinkrels, Constants, utils, GlobalMessage, _lang) {
    'use strict';
    return CommandModel.extend({
      sendRequest: function(view, node, method, url, payload) {
        let deffered = $.Deferred(), me = this;
        me.blockActions(view);
        $.ajax(node.connector.extendAjaxOptions({
            url: url,
            method: method,
            contentType: Constants.MediaTypes.DCTM_JSON,
            data: JSON.stringify(payload)
        })).done(function(data) {
            me.unblockActions(view);
            deffered.resolve(data);
        }).fail(function(jqXHR, textStatus, errorThrown) {
            me.unblockActions(view);
            deffered.reject(jqXHR, textStatus, errorThrown);
        });
        return deffered.promise();
      },

      blockActions: function (view) {
        view && _.isFunction(view.blockActions) && view.blockActions();
      },
      unblockActions: function (view) {
        view && _.isFunction(view.unblockActions) && view.unblockActions();
      },

      createAnnotations: function (view, node) {
        var deferred = $.Deferred();
        let repositoryLink = RestLinkrels.getLink(node.get("links"), RestLinkrels.D2_DOCUMENT_ANNOTATIONS);

        this.sendRequest(view, node, 'POST', repositoryLink)
          .then(function(createdAnnotationData) {
            var annotationID = createdAnnotationData?.annotation_id;
            deferred.resolve(annotationID);
          })
          .fail(function(_jqXHR, _textStatus, errorThrown) {
            deferred.reject(errorThrown);
          });
        return deferred.promise();
      },

      lockAnnotationOrDocument: function(view, node, id, httpMethod) {
        let deferred = $.Deferred(),
        objId = node.get("id");
        if(httpMethod === null || httpMethod === undefined) {
          httpMethod = 'PUT';
        }

        let lockUrl = RestLinkrels.getLink(node.get("links"), RestLinkrels.CHECKOUT);
        lockUrl = lockUrl.replace(objId, id);

        this.sendRequest(view, node, httpMethod, lockUrl)
          .then(function(lockData) {
            CommandHelper.refreshNode(node).done(() => {
              deferred.resolve(lockData);
            });  
          })
          .fail(function(_jqXHR, _textStatus, errorThrown) {
            deferred.reject(errorThrown);
          });
        return deferred.promise();
      },

      getNativeAnnotationsForCollabEdit: function(view, node) {
        var deferred = $.Deferred();
        let nativeAnnotationsLink = RestLinkrels.getLink(node.get("links"), RestLinkrels.D2_NATIVE_ANNOTATIONS_COLLABORATIVE);

        this.sendRequest(view, node, 'GET', nativeAnnotationsLink + "?inline=true")
          .then(function(nativeAnnotationData) {
            deferred.resolve(nativeAnnotationData);
          })
          .fail(function(_jqXHR, _textStatus) { 
            deferred.reject(_jqXHR);
          });
        return deferred.promise();
      },

      batchCallWithNativeAnnotations: function(view, node, nativeAnnotationData){
        let batchPayload = [], me = this;
        me.blockActions(view);
        // preparing data for batch call from Native Annotation Data
      for(let entry of nativeAnnotationData.entries){
        let downloadURL = RestLinkrels.getLink(entry.content.links, RestLinkrels.DOWNLOAD_URLS)

        let blockBatchData = {
          id: entry.id,
          request: {
            method: 'GET',
            uri: downloadURL
          }
        }
        batchPayload.push(blockBatchData);
      }
      let deferred = $.Deferred();

      utils.makeBatchAjaxCall({
        connector: node.connector,
        operations: batchPayload,
        continueOnError: true
      }).done(function (successful, failed) {
        me.unblockActions(view);
        if (failed && failed.length > 0) {
          var errorMessage;
          _.each(failed, function (operation) {
            if (operation.id === 'menuActions' || operation.id === 'userMenu') {
              errorMessage = operation.output.message + "\n";
            } else {
              deferred.reject();
              return;
            }
          });
          if (errorMessage) {
            GlobalMessage.showMessage('error', errorMessage);
          }
        }
        deferred.resolve(successful);
      }).fail(function(errData) {
        me.unblockActions(view);
        deferred.reject(errData);
      });

      return deferred.promise();
      },

      getDownloadData: function(view, node, id) {
        let objId = node.get("id"),
        deferred = $.Deferred();

        let downloadLink = RestLinkrels.getLink(node.get("links"), RestLinkrels.DOWNLOAD_URLS);
        downloadLink = downloadLink.replace(objId, id);

        this.sendRequest(view, node, 'GET', downloadLink)
        .then(function(downloadData) {
          deferred.resolve(downloadData)
        }).fail(function(_jqXHR, _textStatus, errorThrown) {
          deferred.reject(errorThrown);
        })
        return deferred.promise();
      },

      // to be implemented by child object
      execute: function (_status) {
        let deffered = $.Deferred();

        return deffered.promise();
      },

    });
  });

csui.define('d2/commands/collaborative.edit.consolidated',[
    'nuc/lib/jquery',
    'nuc/lib/underscore',
    'dctmw/utils/rest.resources',
    "csui/models/command",
    'csui/utils/commandhelper',
    'd2/utils/rest.linkrels',
    'd2/utils/constants',
    'd2/commands/content-annotations',
    'dctmw/utils/utils',
    'd2/controls/globalmessage/globalmessage',
    'd2/ctf/ctfBridge',
    'd2/ctf/constants',
    'd2/commands/reserve',
    'd2/commands/download'
  ], function ($,_, RestResources, CommandModel, CommandHelper, RestLinkrels, Constants, contentAnnotations, utils, GlobalMessage, ctfBridge, ctfConstants, ReserveCommand, DownloadCommand) {
    'use strict';

    return contentAnnotations.extend({

      defaults: {
        signature: 'D2-ReviewEditConsolidatedCopy',
        command_key: 'D2-ReviewEditConsolidatedCopy',
        scope: 'single'
      },

      reviewAndEditConsolidatedCopy: function (node, status) {
        let me = this;
        let documentObjectId = node.get("id");
        let createdAnnotationId = '';
        let view = status.originatingView;
        me.blockActions(view);
        // step1 : create a new annotation
        this.createAnnotations(view, node)
        .then(function(annotationID) {
          // step2 : lock the annotation
          createdAnnotationId = annotationID;
          return me.lockAnnotationOrDocument(view, node, annotationID);
        })
        .then(function() {
          // step3 : call native annotations for collab edit
          return me.getNativeAnnotationsForCollabEdit(view, node);
        }).then(function(nativeAnnotationsData) {
          // step4 : get download urls 
          return me.batchCallWithNativeAnnotations(view, node, nativeAnnotationsData);
        }).then(function(annotationsContentDownloadData) {
          // step5 : convert the annotationsContentDownloadData to 'ctf.downloadoperation' and 'ctf.nativedownloadoperation' event data 
          // and send to wsctf plugin
          let deferred = $.Deferred();
          let options = {
            connector: node.connector
          };
          // remove the docobjectID
          let docIndex = annotationsContentDownloadData.findIndex(obj => obj.id === documentObjectId);
          if (docIndex !== 1) {
            annotationsContentDownloadData.splice(docIndex, 1);
          }
          const reserveHelper = new ReserveCommand();
          const downloadHelper = new DownloadCommand();
          reserveHelper._validateCtfPath(options).then(function() {
            options.opType = ctfConstants.OpType.VIEW;
            options.mode = ctfConstants.Mode.VIEW;
            reserveHelper._validateCtfPath(options).then(function() {
              const targetFolder = downloadHelper._getDownloadPathForWsCtf(ctfConstants.OpType.CHECKOUT);
              const viewTargetFolder = downloadHelper._getDownloadPathForWsCtf(ctfConstants.OpType.VIEW);
              let createdobjUrl = '';
              let annotationIdsArray = [];
              // // download all the exisitng annotations via 'ctf.downloadoperation' event
              function downloadAnnotations(index) {
                if (index === annotationsContentDownloadData.length) {
                  deferred.resolve({ createdAnnotationId: createdAnnotationId, createdobjUrl: createdobjUrl, annotationIdsArray: annotationIdsArray, targetFolder: targetFolder, viewTargetFolder: viewTargetFolder});               
                  return;
                }
                const annotationContent = annotationsContentDownloadData[index];
                const objId = annotationContent.id;
                annotationIdsArray.push(objId);
                const annotationContentOutput = annotationContent.output;
                let annotationContentUrl = annotationContentOutput.entries[0].content.url;
                if (objId === createdAnnotationId) {
                  createdobjUrl = annotationContentUrl;
                }
                const optype = ctfConstants.OpType.DOWNLOAD;
                const openFile = false;
                ctfBridge.publishDownload(objId, annotationContentUrl, optype, openFile, viewTargetFolder, function () {
                  downloadAnnotations(index + 1);
                },
                (errData) => {
                  deferred.reject(errData);
                });
              }
              downloadAnnotations(0);
            });
          });
          return deferred.promise();
        }).then(async function(nativeDownloadEventData) {
            me.unblockActions(view);
            nativeDownloadEventData.operationType = ctfConstants.OperationType.NATIVE_DOWNLOAD_EDIT_MERGE_SET_REVISION_MODE;
            const nativeobjId = nativeDownloadEventData.createdAnnotationId;
            me.getDownloadData(view, node, nativeobjId).then(async (annotationDownloadData) => {
              const annotationIds = nativeDownloadEventData.annotationIdsArray.join("|");
              const operationType = nativeDownloadEventData.operationType;
              const createdobjUrl = annotationDownloadData?.entries[0]?.content?.url;
              await ctfBridge.publishNativeDownload(nativeobjId, annotationIds, createdobjUrl, operationType, nativeDownloadEventData.viewTargetFolder, nativeDownloadEventData.targetFolder);
            });
        }).fail(function(error) {
          me.unblockActions(view);
          GlobalMessage.showMessage("error",error);
        });
      },

     
      execute: function (status) {
        let node = CommandHelper.getJustOneNode(status);       
        let deffered = $.Deferred();

        this.reviewAndEditConsolidatedCopy(node, status);

        return deffered.promise();
      }
    });
  });
   

csui.define('d2/commands/collaborative.edit.personal',[
  'nuc/lib/jquery',
  'nuc/lib/underscore',
  'dctmw/utils/rest.resources',
  "csui/models/command",
  'csui/utils/commandhelper',
  'd2/utils/rest.linkrels',
  'd2/utils/constants',
  'd2/commands/content-annotations',
  'dctmw/utils/utils',
  'd2/controls/globalmessage/globalmessage',
  'd2/ctf/ctfBridge',
  'd2/ctf/constants',
  'd2/commands/reserve',
  'd2/commands/download'
], function ($,_, RestResources, CommandModel, CommandHelper, RestLinkrels, Constants, contentAnnotations, utils, GlobalMessage, ctfBridge, ctfConstants, ReserveCommand, DownloadCommand) {
  'use strict';

  return contentAnnotations.extend({

    defaults: {
      signature: 'D2-ReviewEditPersonalCopy',
      command_key: 'D2-ReviewEditPersonalCopy',
      scope: 'single'
    },

    reviewAndEditPersonalCopy: function (node, status) {
      let me = this;
      let createdAnnotationId = '';
      let view = status.originatingView;
      me.blockActions(view);
      // step1 : create a new annotation
      me.createAnnotations(view, node)
      .then(function(annotationID) {
          // step2 : checkout/lock the annotation
          createdAnnotationId = annotationID;
          me.lockAnnotationOrDocument(view, node, annotationID).done(() => {
            // step3 : get the download URL of the annotation
            return me.getDownloadData(view, node, annotationID)
            .then(function(annotationDownloadData) {
              // step4 : call wsctf plugin using 'ctf.nativedownload' event data
              me.unblockActions(view);
              const reserveHelper = new ReserveCommand();
              const downloadHelper = new DownloadCommand();
              const annotationDownloadUrl = annotationDownloadData?.entries[0]?.content?.url;
              let options = {
                connector: node.connector
              };
              reserveHelper._validateCtfPath(options).then(function () {
                const targetFolder = downloadHelper._getDownloadPathForWsCtf(ctfConstants.OpType.CHECKOUT);
                ctfBridge.publishNativeDownload(createdAnnotationId, null , annotationDownloadUrl, ctfConstants.OperationType.NATIVE_DOWNLOAD_EDIT_SET_REVISION_MODE, null, targetFolder);
              });
              
            });
          });
      }).fail(function(error) {
        me.unblockActions(view);
        GlobalMessage.showMessage("error", error);
      });
      
    },

    execute: function (status) {
      let node = CommandHelper.getJustOneNode(status);       
      let deffered = $.Deferred();

      this.reviewAndEditPersonalCopy(node, status);

      return deffered.promise();
    }
  });
});
 

csui.define('d2/commands/collaborative.checkout.merge',[
  'nuc/lib/jquery',
  'nuc/lib/underscore',
  'dctmw/utils/rest.resources',
  "csui/models/command",
  'csui/utils/commandhelper',
  'd2/utils/rest.linkrels',
  'd2/utils/constants',
  'd2/commands/content-annotations',
  'dctmw/utils/utils',
  'd2/controls/globalmessage/globalmessage',
  'd2/ctf/ctfBridge',
  'd2/ctf/constants',
  'd2/commands/reserve',
  'd2/commands/download'
], function ($,_, RestResources, CommandModel, CommandHelper, RestLinkrels, Constants, contentAnnotations, utils, GlobalMessage, ctfBridge, ctfConstants, ReserveCommand, DownloadCommand) {
    'use strict';

    return contentAnnotations.extend({
      defaults: {
        signature: 'D2-CollaborativeCheckoutMerge',
        command_key: 'D2-CollaborativeCheckoutMerge',
        scope: 'single'
      },

      checkoutAndMergeCollaborativeChanges: function (node, status) {
        let deferred = $.Deferred();
        let objId = node.get("id"), me = this, view = status.originatingView, objUrl;
        me.blockActions(view);
        if (!node.get("reserved")) {
            me.lockAnnotationOrDocument(view, node, objId);
        }

        me.getNativeAnnotationsForCollabEdit(view, node)
        .then(function(nativeAnnotationData){
            return me.batchCallWithNativeAnnotations(view, node, nativeAnnotationData);

        }).then(function(downloadData){
          // step5 : convert the annotationsContentDownloadData to 'ctf.downloadoperation' and 'ctf.nativedownloadoperation' event data 
          // and send to wsctf plugin
          let deferred = $.Deferred();
          let options = {
            connector: node.connector
          };
          const reserveHelper = new ReserveCommand();
          const downloadHelper = new DownloadCommand();
          reserveHelper._validateCtfPath(options).then(function () {
            options.opType = ctfConstants.OpType.VIEW;
            options.mode = ctfConstants.Mode.VIEW;
            reserveHelper._validateCtfPath(options).then(function() {
              const targetFolder = downloadHelper._getDownloadPathForWsCtf(ctfConstants.OpType.CHECKOUT);
              const viewTargetFolder = downloadHelper._getDownloadPathForWsCtf(ctfConstants.OpType.VIEW);
              let annotationIdsArray = [];
              // // download all the exisitng annotations via 'ctf.downloadoperation' event
              function downloadAnnotations(index) {
                if (index === downloadData.length) {
                  deferred.resolve({ annotationIdsArray: annotationIdsArray, targetFolder: targetFolder, viewTargetFolder: viewTargetFolder});               
                  return;
                }
                const annotationContent = downloadData[index];
                const annotationId = annotationContent.id;
                const annotationContentOutput = annotationContent.output;
                let annotationContentUrl = annotationContentOutput.entries[0].content.url;
                if (annotationId === objId) {
                  objUrl = annotationContentUrl;
                  return downloadAnnotations(index+1);
                }
                annotationIdsArray.push(annotationId);
                const optype = ctfConstants.OpType.DOWNLOAD;
                const openFile = false;
                ctfBridge.publishDownload(annotationId, annotationContentUrl, optype, openFile, viewTargetFolder, function () {
                  downloadAnnotations(index + 1);
                },
                (errData) => {
                  deferred.reject(errData);
                });
              }
              downloadAnnotations(0);
            });
          });
          return deferred.promise();
        }).then(async function(nativeDownloadEventData) {
            me.unblockActions(view);
            nativeDownloadEventData.operationType = ctfConstants.OperationType.NATIVE_DOWNLOAD_EDIT_MERGE_ANNOTATION;
            const annotationIds = nativeDownloadEventData.annotationIdsArray.join("|");
            const operationType = nativeDownloadEventData.operationType;
            await ctfBridge.publishNativeDownload(objId, annotationIds, objUrl, operationType, nativeDownloadEventData.viewTargetFolder, nativeDownloadEventData.targetFolder);
        }).fail(function(error) {
          CommandHelper.refreshNode(node).done(() => {
            deferred.resolve();
            me.lockAnnotationOrDocument(view, node, objId, 'DELETE');
          });
          me.unblockActions(view);
          GlobalMessage.showMessage("error",error.responseJSON.message, error.responseJSON.details);
        });
      },

      execute: function (status) {
        let node = CommandHelper.getJustOneNode(status);       
        let deffered = $.Deferred();

        this.checkoutAndMergeCollaborativeChanges(node, status);

        return deffered.promise();
      }
    });
  });


