csui.define('d2/widgets/favorites/favorite.star.view',[
  'nuc/lib/jquery',
  'nuc/lib/underscore',
  'nuc/lib/marionette',
  'csui/models/favorite.model',
  'csui/controls/progressblocker/blocker',
  'csui/dialogs/modal.alert/modal.alert',
  'd2/server.adaptors/models/widget/favorites/favorites.model',
  'd2/utils/contexts/factories/favorites.factory',
  'nuc/utils/base',
  'dctmw/server.adaptors/converters/node',
  'd2/utils/constants',
  'd2/utils/node.utils',
  'hbs!d2/widgets/favorites/favorite.star/favorite.star.view',
  'i18n!csui/widgets/favorites/impl/nls/lang',
  'css!d2/widgets/favorites/favorite.star/favorite.star.view',
  'csui/controls/icons.v2'
], function ($, _, Marionette, FavoriteModel, BlockingView, ModalAlert, FavoritesCollection, FavoriteCollectionFactory, base, nodeConverter, constants,
             nodeUtils, template, lang) {
  'use strict';

  // This view shows the favorite star view that can be inserted anywhere such as a row cell in the nodes table row, the
  // table header item name's toolbar, etc.
  //
  // Params in the constructor options:
  // - model <required> : the CS node model (NodeModel)
  // - context <required> : the application context object
  // If the node model is already favorited, the star will be solid; otherwise, a non-solid star.
  // Clicking on the star will un-favorite the node model or show a simple add favorite form.
  //

  var NON_FAVORITE_NODE_TYPES = [constants.Types.TASK, constants.Types.TASK_EVENT];

  return Marionette.ItemView.extend({

    template: template,

    templateHelpers: function () {
      return {
        enabled: this.enabled(),
        addFav: lang.addFav,
        removeFav: lang.removeFav,
        iconName: this._iconName,
        selected: this.favModel.get('selected')
      };
    },

    events: {
      'keydown': 'onKeyInView',
      'click': '_onClickView',
      'click a.csui-favorite-star.selected-star': '_clickRemoveFavoriteStar',
      'click a.csui-favorite-star.unselected-star': '_clickAddFavoriteStar'
    },

    constructor: function FavoriteStarView(options) {
      options || (options = {});
      _.defaults(options,{});

      Marionette.ItemView.call(this, options);

      if (options && options.blockingParentView) {
        BlockingView.delegate(this, options.blockingParentView);
      } else {
        BlockingView.imbue(this);
      }
      //fix for the defect DTWO-109124
      //changing the favorites factories from CSUI context to d2 Utils context
      //since favorites widget table view uses d2 utils context favorites factory to sync the collection
      this.favCollection = options.context && options.context.getCollection(FavoriteCollectionFactory, {detached: true});

      // View already has an assigned node model. Use the id of the node model to create a Favorite Model that will send
      // commands to add/remove from Favorites.
      var connector = this.model && this.model.connector;
      var favModelOptions = {};
      if (this.model) {
        favModelOptions = _.extend(
          this._getModelDataForFavoriteModel(),
          {selected: this.model.get('favorite')});
      }
      this.favModel = new FavoriteModel(favModelOptions, {connector: connector});
      this.listenTo(this.favModel, 'change:selected', this.render);
      //DTWO-98435
      this.listenTo(this.model, 'change:favorite', (m, v) => {
        this.favModel.set('selected', v);
      });
    },

    enabled: function () {
      // Exclude special nodes like Repository, Favorites, DQL Root, etc.
      return !!(this.model && this.options.context && this.model.attributes.id && !nodeConverter.isNonDCTMNode(this.model) && !this.isNonFavoriteNode(this.model));
    },

    isNonFavoriteNode: function (model) {
      return _.contains(NON_FAVORITE_NODE_TYPES, model.get('type'));
    },

    onBeforeRender: function () {
      var selected = this.favModel.get('selected');
      this._iconName = selected ? 'csui_action_fav32' : 'csui_action_no_fav32';
    },

    _getModelDataForFavoriteModel: function () {
      return {
        id: this.model.get('id'),
        name: this.model.get('short_name') || this.model.get('name')
      };
    },

    scrollCheckToClosePopover: function () {
      return;
    },

    _onClickView: function (event) {
      // skip if the view is not enabled or the event was triggered by a child element
      if (!this.enabled() || this.$el.find(event.target).length > 0) {
        return;
      }
      if (this.$el.find('.selected-star').length > 0) {
        this._clickRemoveFavoriteStar(event);
      } else {
        this._clickAddFavoriteStar(event);
      }
    },

    _setBlocked: function () {
      // block the command to avoid double clicks or multiple fast clicks
      this.commandBlocked = true;
      setTimeout(_.bind(function () {
        this.commandBlocked = false;
      }, this), 500);
    },

    _clickAddFavoriteStar: function (event) {
      event && event.preventDefault();
      if (this.commandBlocked) {
        return;
      }
      this._setBlocked();
      // always initialize favModel for re-initialization if changed
      this.favModel.set(this._getModelDataForFavoriteModel());
      this._addFavoriteToServer();
    },

    _clickRemoveFavoriteStar: function (event) {
      event && event.preventDefault();
      if (this.commandBlocked) {
        return;
      }
      this._setBlocked();
      this._removeFavoriteFromServer();
    },

    _removeFavoriteFromClientSideCollection: function (/*listenToEvent*/) {
      if (this.options?.tableView?.collection instanceof FavoritesCollection) {
        return;
      }
      var self = this;
      this.model.set('favorite', false, {silent: true});
      this.$el.trigger('favorite:change', [this.model]);
      this.favCollection.remove(this.favCollection.findWhere({
        id: self.favModel.get('id')
      }));
    },

    _removeFavoriteFromServer: function () {
      var self = this;
      this.blockActions();
      this.favModel.removeFromFavorites()
        .always(function (/*data*/) {
          self.unblockActions();
        })
        .done(function (/*resp*/) {
          self._removeFavoriteFromClientSideCollection();
        })
        .fail(function (err) {
          self._showErrorMessage(self.favModel, err);
        });
    },

    _addFavoriteToClientSideCollection: function (/*listenToEvent*/) {
      if (this.options?.tableView?.collection instanceof FavoritesCollection) {
        return;
      }
      this.model.set('favorite', true, {silent: true});
      this.$el.trigger('favorite:change', [this.model]);
      var model = this.model.clone(),
        name = this.favModel.get('name'),
        origProps = model.get('_orig_properties');
      if (model.get('id') === nodeUtils.getHomeCabinetId()) {
        name = (origProps && origProps.object_name) || name;
      }
      model.set({
        name: name,
        short_name: name,
        favorite: true
      });
      this.favCollection.add(model);
    },

    _addFavoriteToServer: function () {
      var deferred = $.Deferred();
      var self = this;
      this.blockActions();
      this.favModel.addToFavorites()
        .always(function (/*data*/) {
          self.unblockActions();
        })
        .done(function (resp) {
          deferred.resolve(resp);
          self._addFavoriteToClientSideCollection();
        })
        .fail(function (err) {
          deferred.reject(err);
          self._showErrorMessage(self.favModel, err);
        });
      return deferred.promise();
    },

    _showErrorMessage: function (model, iError) {
      var error = new base.Error(iError);
      var title = lang.updateFavoriteFailTitle;
      var message = _.str.sformat(lang.updateFavoriteFailMessage, model.get('id'), error.message);
      ModalAlert.showError(message, title);
    },

    toggleFavorite: function () {
      if (this.model.get('favorite')) {
        this._clickRemoveFavoriteStar();
      } else {
        this._clickAddFavoriteStar();
      }
    },

    onKeyInView: function (event) {
      if (event.keyCode === 32 || event.keyCode === 13) {
        // space or enter key
        this.enabled() && this.toggleFavorite();
        // stop propogation only for enter and space , other key events like left/right need to be
        // sent to table.body.view to move up/down and left right
        event.preventDefault();
        event.stopPropagation();
      }

    },

    // This is for JS error in thumbnail view
    closePopover: function () {
    }

  });

});


