          column_key: "modify_date",
          d2_sort_key: "modify_date",
          default_action: true,
          definitions_order: 521,
          direction: "",
          key: "modify_date",
          name: lang.savedSearchTableColumnModifyDate,
          repeating: false,
          sort: true,
          title: lang.savedSearchTableColumnModifyDate,
