      pieFillColor: '#1e7e40',
      highlightColor: '#333333', // donut chart highlight color
      textColor: '#333333',
      totalCountColor: '#757575',
      innerCircleStrokeColor: '#E7EDF8',
      innerCircleFillColor: '#ffffff',
      innerCircleRadius: '42',
      donutRadius: '72',
      totalLabel: lang.defaultTotalLabel
