csui.define('d2/dialogs/new.file/edit/edit.content.view',[
  'nuc/lib/jquery',
  'nuc/lib/marionette',
  'nuc/lib/backbone',
  'nuc/lib/underscore',
  'csui/controls/tile/behaviors/perfect.scrolling.behavior',
  'd2/controls/behaviors/wizard.tabable.region.behavior',
  'd2/commands/reserve',
  'd2/dialogs/new.file/edit/button.icon.layout.view',
  'd2/dialogs/new.file/edit/header.message.view',
  'dctmw/utils/rest.resources',
  'd2/utils/rest.linkrels',
  'dctmw/utils/utils',
  'd2/utils/constants',
  'd2/ctf/ctfBridge',
  'hbs!d2/dialogs/new.file/edit/impl/edit.content',
  'i18n!d2/dialogs/new.file/edit/impl/nls/lang',
  'i18n!d2/commands/nls/localized.strings',
  'css!d2/dialogs/new.file/edit/impl/edit.content'
], function ($, Marionette, Backbone, _, PerfectScrollingBehavior, WizardTabableRegionBehavior, ReserveCommand, ButtonIconLayoutView, HeaderMessageView, RestResources, RestLinkrels, utils, constants, ctfBridge, template, lang, commandLang) {
  'use strict';

  return Marionette.LayoutView.extend({
    className: 'd2-edit-content',

    template: template,

    regions: {
      buttonRegion: '.button-region'
    },

    behaviors: {
      PerfectScrolling: {
        behaviorClass: PerfectScrollingBehavior,
        suppressScrollX: true,
        scrollYMarginOffset: 15
      },
      TabableRegion: {
        behaviorClass: WizardTabableRegionBehavior
      }
    },

    constructor: function EditContentView(/*options*/) {
      Marionette.LayoutView.prototype.constructor.apply(this, arguments);

      this.buttonIconLayoutView = new ButtonIconLayoutView({
        collection: new Backbone.Collection([{
          id: 'edit_now',
          label: lang.EditNow,
          iconClass: 'd2-icon-edit-now'
        }, {
          id: 'edit_later',
          label: lang.EditLater,
          iconClass: 'd2-icon-edit-later'
        }])
      });

      this.fetchDataForContentEdit();
      this.listenTo(this.buttonIconLayoutView, 'button:click', this.onButtonClick);
    },

    prependMessage: function (mode, message) {
      this.$el.find('.d2-header-message-container.'+mode).remove();
      if (mode && message) {
        var messageView = new HeaderMessageView({
          message: message,
          mode: mode
        });
        messageView.render();
        this.$el.prepend(messageView.$el);
      }
    },

    fetchDataForContentEdit: function () {
      //TODO: linkrel
      var url = RestLinkrels.getLink(this.options.node.get('links'), RestLinkrels.CHECKOUT_PRECHECK),
        me = this;

      function commitPendingObjects() {
        return me.options.action.commitFile(me.options.node, me.options.wizard);
      }

      function reserveFile() {
        me.options.node.contentCreatedBeforeEdit = true;
        $.ajax(me.options.node.connector.extendAjaxOptions({
          url: url,
          success: function (response) {
            switch (response.status) {
              case 'WARNING':
                me.prependMessage('warning', response.message);
                break;
              case 'ERROR':
                me.prependMessage('error', response.message);
                me.disableEditNow();
                break;
              default:
                me.prependMessage();
                break;
            }
            me.options.wizard.unblockActions();
          },
          error: function (xhr, textStatus, errorThrown) {
            me.prependMessage('error', utils.parseAjaxErrorAsString(xhr, textStatus, errorThrown));
            me.disableEditNow();
            me.options.wizard.unblockActions();
          }
        }));
      }

      me.options.wizard.blockActions();
      if (me.options.action.isLinkedDoc === true) {
        me.options.wizard.unblockActions();
        reserveFile();
      } else {
        commitPendingObjects().always(function () {
          var linkedNodes = me.options.action._getLinkedNodes(me.options.node, me.options.wizard),
            msg = commandLang.CreateItemSuccessMessageFormat;
          if (linkedNodes && linkedNodes.length > 0) {
            msg = commandLang.CreateItemSuccessMessageFormatWithLink;
          }
          me.prependMessage('success', _.str.sformat(msg, me.options.node.get('name')));
          reserveFile();
        });
      }
    },

    disableEditNow: function () {
      var buttonView = this.buttonIconLayoutView.children.findByModel(this.buttonIconLayoutView.collection.findWhere({id: 'edit_now'}));
      buttonView.disable();
    },

    onButtonClick: function (model) {
      switch (model.get('id')) {
        case 'edit_now':
          this.onClickEditNow();
          break;
        case 'edit_later':
          this.onClickEditLater();
          break;
      }
    },

    onClickEditNow: function () {
      //TODO: WSCTF
      var node = this.options.node,
        me = this;

      me.getInitialDataForCheckout(node).done(function () {
        me.options.wizard.blockActions();
        $.ajax(node.connector.extendAjaxOptions({
          type: 'PUT',
          url: RestLinkrels.getLink(me.options.node.get('links'), RestLinkrels.CHECKOUT),
          success: function (response) {
            node.set('links', node.get('links').concat(response.links));
            var dlHelper = me.options.downloadHelper,
              downloadLink = dlHelper.getDownloadLink(node);
            if (!downloadLink) {
              me.contentLessObject = true;
            }
            if (ctfBridge.isCtfEnabled()) {
              me.options.wizard.unblockActions();
              me.options.wizard.nextStep();
            } else {
              if (downloadLink) {
                dlHelper._downloadContent(node);
              }
              me.options.wizard.unblockActions();
              me.options.wizard.nextStep();
            }
          },
          error: function (/*xhr, textStatus, errorThrown*/) {
            me.prependMessage('error', _.str.sformat(lang.CheckoutFailed, node.get('name')));
            me.disableEditNow();
            me.options.wizard.unblockActions();
          }
        }));
      });
    },

    getInitialDataForCheckout: function (node) {
      var deferred = $.Deferred();
      if (ctfBridge.isCtfEnabled()) {
        var reserveCommand = new ReserveCommand();
        reserveCommand._validateCtfPath({
          connector: node.connector
        }).done(function () {
          var pref = RestResources.getCurrentUser().get('preferences'),
            checkoutPath = pref[constants.UserSettings.DOWNLOAD_CHECKOUT_PATH];
          if (checkoutPath) {
            deferred.resolve();
          } else {
            deferred.reject();
          }
        }).fail(deferred.reject);
      } else {
        deferred.resolve();
      }
      return deferred.promise();
    },

    getNextStep: function () {
      if (this.editContentLater) {
        return 'finish';
      }
      var nextStep = this.options.action.STEPS.ADD_VERSION;
      if (ctfBridge.isCtfEnabled() && !this.contentLessObject) {
        nextStep = this.options.action.STEPS.DOWNLOADING_CONTENT;
      }
      return nextStep;
    },

    onClickEditLater: function () {
      this.editContentLater = true;
      this.options.wizard.close();
    },


    getTitle: function () {
      return (this.options.action.isLinkedDoc === true) ? lang.EditLinkedDocumentContentTitle : lang.EditContentTitle;
    },

    getCancelLabel: function () {
      return lang.CancelLabel;
    },

    onRender: function () {
      this.buttonRegion.show(this.buttonIconLayoutView);
    },

    onShow: function () {
      this.$el.closest('.d2-wizard-step-view').css('top', '0');
    }
  });
});

csui.define('d2/dialogs/new.file/edit/created.content.processing.view',[
  'nuc/lib/underscore',
  'nuc/lib/jquery',
  'nuc/lib/backbone',
  'nuc/lib/marionette',
  'd2/utils/rest.linkrels',
  'd2/utils/constants',
  'd2/ctf/constants',
  'd2/dialogs/new.file/o2.processing.view',
  'd2/ctf/ctfBridge',
  'i18n!d2/dialogs/new.file/edit/impl/nls/lang'
], function (_, $, Backbone, Marionette, RestLinkrels, constants, ctfConstants, O2ProcessingView, ctfBridge, lang) {
  'use strict';

  var DowloadFileProcessingView = O2ProcessingView.extend({
    className: function () {
      return O2ProcessingView.prototype.className + ' d2-create-download-processing';
    },

    constructor: function DowloadFileProcessingView(/*options*/) {
      O2ProcessingView.prototype.constructor.apply(this, arguments);
    },

    getTitle: function () {
      return (this.options.mode === 'UPLOAD') ? lang.UploadingStepTitle : lang.DownloadingStepTitle
    },

    initialize: function () {
      return;
    },

    isProcessingRequired: function () {
      return true;
    },

    templateHelpers: function () {
      return {
        labelProcessing: (this.options.mode === 'UPLOAD') ? lang.UploadingLabel : lang.DownloadingLabel,
        percentage: 0
      };
    },

    onStepActive: function () {
      if (this.isProcessingRequired()) {
        if(this.options.mode === 'UPLOAD'){
          this.$el.closest('.binf-modal-dialog').find('.binf-modal-header .cs-close').addClass('binf-hidden');
        }
        this.pendingDfd = $.Deferred();
        var node = this.options.node;
        this.getProcessingPromise(node)
          .always(this.pendingDfd.resolve)
          .progress(this.updateProgress.bind(this))
          .done(this.handleProcessingSuccess.bind(this))
          .fail(this.handleProcessingFailure.bind(this));
        return;
      }
      this.wizard && this.wizard.nextStep();
    },

    handleProcessingSuccess: function() {
      if(this.wizardMinimized) {
        //Hold it until the wizard is restored
        this.listenToOnce(this.wizard, 'wizard:restored', this.handleProcessingSuccess.bind(this));
      } else {
        this.gotoNextStep();
      }
    },

    handleProcessingFailure: function(error) {
      if(this.wizardMinimized) {
        //Hold it until the wizard is restored
        this.listenToOnce(this.wizard, 'wizard:restored', this.handleProcessingFailure.bind(this, error));
      } else {
        this.options.checkinData['downloadError'] = error;
        this.gotoNextStep();
      }
    },

    updateProgress: function (progressData) {
      var percentage = (progressData.done / progressData.total) * 100;
      this.ui.progressBar.width(percentage + '%');
      this.ui.progressBar.attr('aria-valuenow', percentage);
    },

    getProcessingPromise: function (node) {
      if (this.options.mode === 'UPLOAD') {
        var fileUploaderOptions = this.options.wizard.data.checkinData.fileUploaderOptions;
        return this.options.action.uploadContentUsingFileUploader(node, fileUploaderOptions);
      } else {
        return this.downloadCreatedContentUsingWsctf(node);
      }
    },

    downloadCreatedContentUsingWsctf: function (node) {
      var deferred = $.Deferred(),
        dlHelper = this.options.downloadHelper,
        downloadLink = dlHelper.getDownloadLink(node);

      if (downloadLink) {
        dlHelper.fetchDownloadUrls(node, downloadLink).done(function (urls,  pageServingUrls, bravacsrSearchInfoUrl, bravacsrSearchInfoFallbackUrl,
          formats, pageCount, downloadLocationPath) {
          dlHelper._performDownloadUsingWsCtf(urls, node, ctfConstants.OpType.CHECKOUT, ctfConstants.Mode.EDIT, true, true, true, downloadLocationPath.checkout)
            .progress(deferred.notify)
            .done(deferred.resolve)
            .fail(deferred.reject);
        }).fail(deferred.reject);
      } else {
        this.gotoNextStep();
        deferred.resolve();
      }

      return deferred.promise();
    },

    getNextStepId:function(){
      return 'finish';
    },

    getMinimizelabels: function(){
      return {
        ProcessingHeaderTitle: _.str.sformat((this.options.mode === 'UPLOAD') ? lang.ProcessingUploadHeaderTitle : lang.ProcessingDownloadHeaderTitle , this.options.node.get("name")),
        CompletedHeaderTitle: _.str.sformat((this.options.mode === 'UPLOAD') ? lang.CompletedDownloadHeaderTitle : lang.CompletedDownloadHeaderTitle, this.options.node.get("name"))
      }
    }

  });
  return DowloadFileProcessingView;
});

