  'csui/behaviors/keyboard.navigation/tabable.region.behavior',
  'd2/utils/rest.linkrels',
  'dctmw/utils/utils',
  'd2/utils/constants',
  'd2/dialogs/share.to.core/impl/share.to.core.permission.view',
  'i18n!d2/dialogs/share.to.core/impl/nls/lang',
