        pickerOptions.storeContainer = true;
        pickerOptions.restoreContainer = true;
        pickerOptions.dataId = constants.StorageKey.LAUNCH_WORKFLOW_ATTACHMENTS_VIEW_MIXIN + constants.StorageKey.ANCESTOR_INFO;

