        viewStateModel.set(viewStateModel.CONSTANTS.DEFAULT_STATE, defaultState, {silent: true});
        this.addUrlParameters(TaskViewStateMixin.PROPERTY_CONSTANTS.DETAILS_PERSPECTIVE_INIT_URL_PARAMS);
