  'nuc/lib/underscore',
  'nuc/lib/jquery',
  'nuc/lib/backbone',
  'nuc/lib/marionette',
  'csui/utils/nodesprites',
  'dctmw/server.adaptors/converters/node',
  'd2/controls/behaviors/wizard.tabable.region.behavior',
  'csui/controls/tile/behaviors/perfect.scrolling.behavior',
  'dctmw/utils/utils',
  'i18n!d2/dialogs/zipanddownload/impl/nls/lang',
  'hbs!d2/dialogs/zipanddownload/zip.download.error.list/impl/zip.download.error.layout.view',
