  'dctmw/utils/rest.resources',
  'd2/utils/widget.constants',
  "d2/utils/contexts/factories/d2.mycollections.factory",
  "d2/utils/contexts/factories/d2.sharedcollections.factory",
  "d2/models/d2collections/d2collections.items.collection",
